local function loadConfig()
    local file = io.open(CONFIG_PATH, 'rb')
    if not file then return end
    for line in file:lines() do
        line = line:gsub('\r', '')
        local key, value = line:match('^([%w_]+)=(.*)$')
        if key and defaults.main[key] ~= nil then
            loadedConfigKeys[key] = true
            if type(defaults.main[key]) == 'number' then
                config.main[key] = tonumber(value) or defaults.main[key]
            elseif type(defaults.main[key]) == 'boolean' then
                config.main[key] = value == 'true'
            else
                config.main[key] = value
            end
        end
    end
    file:close()
end

