function readNameList(value)
    local list, seen = {}, {}
    for name in tostring(value or ''):gmatch('[^|]+') do
        name = name:match('^%s*(.-)%s*$')
        if name ~= '' and not seen[name] then
            seen[name] = true
            list[#list + 1] = name
        end
    end
    return list, seen
end

