local function fromBuffer(buffer)
    return u8:decode(ffi.string(buffer))
end

local function setBuffer(buffer, size, value)
    ffi.fill(buffer, size)
    value = u8(tostring(value or ''))
    ffi.copy(buffer, value, math.min(#value, size - 1))
end

local function setBufferIfChanged(buffer, value)
    value = tostring(value or '')
    if fromBuffer(buffer) ~= value then setBuffer(buffer, ffi.sizeof(buffer), value) end
end

local function trim(value)
    return tostring(value or ''):match('^%s*(.-)%s*$')
end

function editorHexEncode(value)
    return (tostring(value or ''):gsub('.', function(char)
        return string.format('%02X', char:byte())
    end))
end

function editorHexDecode(value)
    if type(value) ~= 'string' or value:find('[^%x]') or #value % 2 ~= 0 then return '' end
    return (value:gsub('%x%x', function(pair)
        return string.char(tonumber(pair, 16))
    end))
end

function serializeEditorEntries(entries, valueKey)
    local result = {}
    for _, entry in ipairs(entries or {}) do
        local name = trim(entry.name):lower()
        local value = tostring(entry[valueKey] or '')
        if name ~= '' and value ~= '' then
            result[#result + 1] = editorHexEncode(name) .. ':' .. editorHexEncode(value)
        end
    end
    return table.concat(result, '|')
end

function parseEditorEntries(value, valueKey)
    local result = {}
    for record in tostring(value or ''):gmatch('[^|]+') do
        local nameHex, valueHex = record:match('^([^:]+):([^:]+)$')
        local name = editorHexDecode(nameHex):lower()
        local decoded = editorHexDecode(valueHex)
        if name:match('^[%w_]+$') and decoded ~= '' then
            result[#result + 1] = { name = name, [valueKey] = decoded }
        end
    end
    return result
end

function serializeActionHotkeys()
    local ids, result = {}, {}
    for id in pairs(actionHotkeys) do ids[#ids + 1] = id end
    table.sort(ids)
    for _, id in ipairs(ids) do
        local binding = actionHotkeys[id]
        result[#result + 1] = table.concat({ id, tonumber(binding.key1) or 0,
            tonumber(binding.key2) or 0, binding.useSecond and 1 or 0 }, ',')
    end
    return table.concat(result, '|')
end

function parseActionHotkeys(value)
    local result = {}
    for record in tostring(value or ''):gmatch('[^|]+') do
        local id, key1, key2, useSecond = record:match('^([%w_]+),(%d+),(%d+),([01])$')
        if id then
            result[id] = {
                key1 = math.max(0, math.min(255, tonumber(key1) or 0)),
                key2 = math.max(0, math.min(255, tonumber(key2) or 0)),
                useSecond = useSecond == '1', wasDown = false
            }
        end
    end
    return result
end

function applyRecommendedActionHotkeys()
    local recommended = {
        m55 = { 0x4D, 0x31 }, m66 = { 0x4D, 0x32 },
        yield_road = { 0x4D, 0x33 }, road_code = { 0x4D, 0x34 },
        do_not_interfere = { 0x4D, 0x35 }, stop_chase = { 0x4D, 0x36 },
        traffic_contact = { 0x4A, 0x31 }, udo = { 0x4A, 0x32 },
        passport = { 0x4A, 0x33 }, passport_license = { 0x4A, 0x34 },
        rights = { 0x4A, 0x35 }, federal_surrender = { 0x4A, 0x36 },
        shout = { 0x4A, 0x37 }, leave_area = { 0x4A, 0x38 },
        verbal_warning = { 0x4A, 0x39 },
        radio_status = { 0x4B, 0x31 }, backup = { 0x4B, 0x32 }, sos = { 0x4B, 0x33 },
        mask = { 0x4C, 0x31 }, healme = { 0x4C, 0x32 },
        fix = { 0x4C, 0x33 }, bodycam = { 0x4C, 0x34 },
        input_cf = { 0x49, 0x31 }, input_hd = { 0x49, 0x32 },
        input_pl = { 0x49, 0x33 }, input_pg = { 0x49, 0x34 },
        input_vn = { 0x49, 0x35 }, input_y = { 0x49, 0x36 }
    }
    for id, keys in pairs(recommended) do
        actionHotkeys[id] = { key1 = keys[1], key2 = keys[2], useSecond = true, wasDown = false }
    end
end

