local cpUpper = 'АБВГДЕЁЖЗИЙКЛМНОПРСТУФХЦЧШЩЪЫЬЭЮЯ'
local cpLower = 'абвгдеёжзийклмнопрстуфхцчшщъыьэюя'
local cpLowerMap = {}
local cpUpperMap = {}
for index = 1, #cpUpper do
    cpLowerMap[cpUpper:sub(index, index)] = cpLower:sub(index, index)
    cpUpperMap[cpLower:sub(index, index)] = cpUpper:sub(index, index)
end

local function lowerCp1251(text)
    return (tostring(text or ''):gsub('.', cpLowerMap)):lower()
end

local function addLog(text)
    -- Журнал намеренно не хранится: интерфейс показывает только текущее действие.
end

local function notify(text, color)
    if isSampAvailable() then
        -- Второй аргумент окрашивает системный таймстамп до первого цветового кода.
        -- Белый базовый цвет сохраняет время нейтральным, а префикс красится сам.
        sampAddChatMessage(CHAT_PREFIX .. text, -1)
    end
end

function protectedError(scope, err)
    local message = tostring(err or 'неизвестная ошибка')
    print('[PoliceHelper] Защищённая ошибка в ' .. tostring(scope) .. ': ' .. message)
    pcall(function()
        if isSampAvailable() then sampAddChatMessage(CHAT_PREFIX .. 'Действие остановлено из-за внутренней ошибки. Подробности сохранены в moonloader.log.', -1) end
    end)
end

function safeCommandCall(name, handler, args)
    local ok, result = xpcall(function() return handler(args or '') end, debug.traceback)
    if not ok then protectedError('команде /' .. name, result); return end
    return result
end

function registerSafeCommand(name, handler)
    local ok, err = pcall(sampRegisterChatCommand, name, function(args)
        return safeCommandCall(name, handler, args)
    end)
    if not ok then protectedError('регистрации /' .. name, err) end
end

function safeFrame(scope, callback)
    local ok, err = xpcall(callback, debug.traceback)
    if not ok then
        window[0], quickMenu[0], animationWindow[0], interviewWindow[0] = false, false, false, false
        wantedSelector[0], ticketSelector[0], sosConfirm[0], updateConfirm[0] = false, false, false, false
        targetRadialMenu.open = false
        targetRadialMenu.clickPending = false
        protectedError('интерфейсе ' .. scope, err)
    end
end

function selectedInterfaceFont()
    return interfaceFonts and interfaceFonts[interfaceFontSize] or nil
end

function safeInterfaceFrame(scope, callback)
    local font = selectedInterfaceFont()
    local pushed = false
    if font then pushed = pcall(imgui.PushFont, font) end
    safeFrame(scope, callback)
    if pushed then pcall(imgui.PopFont) end
end

-- Динамический текст нельзя передавать в TextWrapped как формат:
-- символ % в статьях будет воспринят нативным ImGui как printf-спецификатор.
function policeHelperSafeWrappedText(value)
    local converted, text = pcall(u8, tostring(value or ''))
    if not converted or not text then text = u8'[Не удалось отобразить текст]' end
    local pushed = pcall(imgui.PushTextWrapPos, 0.0)
    local rendered = pcall(imgui.TextUnformatted, text)
    if pushed then pcall(imgui.PopTextWrapPos) end
    if not rendered then pcall(imgui.TextUnformatted, u8'[Ошибка вывода текста]') end
end

function safeEventCall(scope, handler, ...)
    local arguments = { ... }
    local ok, first, second = xpcall(function()
        return handler(unpack(arguments))
    end, debug.traceback)
    if not ok then protectedError('событии ' .. scope, first); return end
    return first, second
end

runtimeErrorTimes = {}
function safeRuntimeCall(scope, callback)
    local ok, first, second = xpcall(callback, debug.traceback)
    if not ok then
        local now = os.clock()
        if now - (runtimeErrorTimes[scope] or -100.0) >= 5.0 then
            runtimeErrorTimes[scope] = now
            protectedError('фоновом модуле ' .. scope, first)
        end
        return false
    end
    return true, first, second
end

function installThreadProtection()
    if policeHelperThreadProtectionInstalled then return end
    policeHelperThreadProtectionInstalled = true
    -- Нельзя оборачивать весь MoonLoader-поток в pcall/xpcall: callback использует wait(),
    -- а приостановка через защищённый C-вызов повреждает состояние coroutine.
    -- Ошибкоопасные действия защищаются локально, между точками ожидания.
end
installThreadProtection()

function selectedEquipmentString()
    local selected = {}
    for _, itemName in ipairs(equipmentKnown) do
        local choice = equipmentChoices[itemName]
        if choice and choice[0] then selected[#selected + 1] = itemName end
    end
    return table.concat(selected, '|')
end

local function saveConfig()
    config.main.delay = delayMs[0]
    config.main.delayDefaultVersion = 3
    config.main.department = fromBuffer(departmentBuf)
    config.main.rank = fromBuffer(rankBuf)
    config.main.radioTag = fromBuffer(radioTagBuf)
    config.main.factionTag = fromBuffer(factionTagBuf)
    config.main.vehicle = fromBuffer(vehicleBuf)
    config.main.city = fromBuffer(cityBuf)
    config.main.location = fromBuffer(locationBuf)
    config.main.crew = fromBuffer(crewBuf)
    config.main.profileMode = profileManual[0] and 'manual' or 'auto'
    config.main.hideAds = hideAds[0]
    config.main.resetAfterMask = resetAfterMask[0]
    config.main.autoMaskRenew = autoMaskRenew[0]
    config.main.autoEat = autoEat[0]
    config.main.autoFuel = autoFuel[0]
    config.main.autoReportDamager = autoReportDamager[0]
    config.main.autoReportTracked = autoReportTracked[0]
    config.main.autoRadioReports = autoRadioReports[0]
    config.main.commandAliases = serializeEditorEntries(commandAliases, 'target')
    config.main.customCommands = serializeEditorEntries(customCommands, 'body')
    config.main.actionHotkeys = serializeActionHotkeys()
    config.main.actionHotkeyLayoutVersion = 8
    config.main.autoEquipment = autoEquipment[0]
    config.main.weaponRoleplay = weaponRoleplay[0]
    config.main.equipmentKnown = table.concat(equipmentKnown, '|')
    config.main.equipmentSelected = selectedEquipmentString()
    config.main.whiteMaskedChatIds = whiteMaskedChatIds[0]
    config.main.whiteNametagIds = whiteNametagIds[0]
    config.main.hideVChannel = hideVChannel[0]
    config.main.hideJobChannels = hideJobChannels[0]
    config.main.hideGChannel = hideGChannel[0]
    config.main.hidePChannel = hidePChannel[0]
    config.main.hideGovNews = hideGovNews[0]
    config.main.hideFamilyChat = hideFamilyChat[0]
    config.main.roleplayOverrides = serializeEditorEntries(roleplayOverrides, 'body')
    config.main.strobesEnabled = strobesEnabled[0]
    config.main.cruiseEnabled = cruiseEnabled[0]
    config.main.strobeKey1 = strobeKey1[0]
    config.main.strobeKey2 = strobeKey2[0]
    config.main.strobeUseSecond = strobeUseSecond[0]
    config.main.cruiseKey1 = cruiseKey1[0]
    config.main.cruiseKey2 = cruiseKey2[0]
    config.main.cruiseUseSecond = cruiseUseSecond[0]
    config.main.interfaceFontSize = interfaceFontSize
    config.main.quickKey1 = quickKey1[0]
    config.main.quickKey2 = quickKey2[0]
    config.main.quickUseSecond = quickUseSecond[0]
    config.main.mainKey1 = mainKey1[0]
    config.main.mainKey2 = mainKey2[0]
    config.main.mainUseSecond = mainUseSecond[0]
    config.main.hotkeyLayoutVersion = 1
    local file = io.open(CONFIG_PATH, 'wb')
    if not file then return false end
    file:write('[main]\r\n')
    for _, key in ipairs({ 'delay', 'delayDefaultVersion', 'department', 'rank', 'profileMode', 'radioTag', 'factionTag', 'vehicle', 'city', 'location', 'crew', 'hideAds', 'resetAfterMask', 'autoMaskRenew', 'autoEat', 'autoFuel', 'autoReportDamager', 'autoReportTracked', 'autoRadioReports', 'commandAliases', 'customCommands', 'roleplayOverrides', 'actionHotkeys', 'actionHotkeyLayoutVersion', 'autoEquipment', 'weaponRoleplay', 'equipmentKnown', 'equipmentSelected', 'whiteMaskedChatIds', 'whiteNametagIds', 'hideVChannel', 'hideJobChannels', 'hideGChannel', 'hidePChannel', 'hideGovNews', 'hideFamilyChat', 'strobesEnabled', 'cruiseEnabled', 'strobeKey1', 'strobeKey2', 'strobeUseSecond', 'cruiseKey1', 'cruiseKey2', 'cruiseUseSecond', 'interfaceFontSize', 'quickKey1', 'quickKey2', 'quickUseSecond', 'mainKey1', 'mainKey2', 'mainUseSecond', 'hotkeyLayoutVersion' }) do
        local value = tostring(config.main[key]):gsub('[\r\n]', '')
        file:write(key .. '=' .. value .. '\r\n')
    end
    file:close()
    return true
end

local function stripColorCodes(text)
    return tostring(text or ''):gsub('{%x%x%x%x%x%x}', '')
end

function validRawGithubUrl(url)
    return type(url) == 'string' and url:match('^https://raw%.githubusercontent%.com/') ~= nil
end

function updateUrl(url)
    local separator = url:find('?', 1, true) and '&' or '?'
    return url .. separator .. 'policehelper=' .. os.time() .. math.random(1000, 9999)
end

function formatReleaseTimestamp(version)
    local day, month, year, hour, minute = tostring(version or '')
        :match('^(%d%d)(%d%d)(%d%d%d%d)_(%d%d)(%d%d)%d%d$')
    if not day then return tostring(version or '') end
    return string.format('%s.%s.%s %s:%s', day, month, year, hour, minute)
end

function releaseVersionKey(version)
    local day, month, year, hour, minute, second = tostring(version or '')
        :match('^(%d%d)(%d%d)(%d%d%d%d)_(%d%d)(%d%d)(%d%d)$')
    if not day then return nil end
    return year .. month .. day .. hour .. minute .. second
end

function isReleaseVersionNewer(candidate, current)
    local candidateKey = releaseVersionKey(candidate)
    local currentKey = releaseVersionKey(current)
    return candidateKey ~= nil and currentKey ~= nil and candidateKey > currentKey
end

function removeUpdateTemp(path)
    if type(path) == 'string' and path ~= '' and doesFileExist(path) then
        local ok, err = os.remove(path)
        if not ok then print('[PoliceHelper] Не удалось удалить временный файл обновления: ' .. tostring(err)) end
    end
end

function cleanupUpdateBackups()
    local scriptPath = thisScript().path
    local directory = scriptPath:match('^(.*[\\/])') or ''
    local scriptName = scriptPath:match('([^\\/]+)$') or 'PoliceHelper.lua'
    local escapedName = scriptName:gsub('([^%w])', '%%%1')
    local mask = scriptPath .. '.update.*.bak'
    local opened, handle, name = pcall(findFirstFile, mask)
    if not opened or not handle then return end

    while name do
        if name:match('^' .. escapedName .. '%.update%.%d+%.bak$') then
            local removed, removeError = os.remove(directory .. name)
            if not removed then
                print('[PoliceHelper] Не удалось удалить старую резервную копию: ' .. tostring(removeError))
            end
        end
        local nextOk, nextName = pcall(findNextFile, handle)
        if not nextOk then break end
        name = nextName
    end
    pcall(findClose, handle)
end

function getUpdateFileSize(path)
    local file = io.open(path, 'rb')
    if not file then return 0 end
    local size = file:seek('end') or 0
    file:close()
    return size
end

function updaterMessage(text, color)
    if updateState.verbose and isSampAvailable() and sampIsLocalPlayerSpawned() then
        notify(text, color)
    else
        print('[PoliceHelper] ' .. tostring(text))
    end
end

function queueUpdaterEvent(kind, token, path, version)
    if token ~= updateState.token then return end
    updateState.event = { kind = kind, token = token, path = path, version = version }
end

function installDownloadedUpdate(path, latestVersion)
    if not doesFileExist(path) or getUpdateFileSize(path) < 1024 then
        updateState.downloading = false
        removeUpdateTemp(path)
        updaterMessage('Обновление отклонено: загруженный файл отсутствует или слишком мал.', 0xFF7777)
        return
    end
    local chunk, syntaxError = loadfile(path)
    if not chunk then
        updateState.downloading = false
        removeUpdateTemp(path)
        updaterMessage('Обновление отклонено: загруженный Lua содержит ошибку.', 0xFF7777)
        print('[PoliceHelper] Ошибка обновления: ' .. tostring(syntaxError))
        return
    end

    local scriptPath = thisScript().path
    local backupPath = scriptPath .. '.update.' .. os.time() .. '.bak'
    local backedUp, backupError = os.rename(scriptPath, backupPath)
    if not backedUp then
        updateState.downloading = false
        removeUpdateTemp(path)
        updaterMessage('Не удалось создать резервную копию обновления.', 0xFF7777)
        print('[PoliceHelper] ' .. tostring(backupError))
        return
    end

    local installed, installError = os.rename(path, scriptPath)
    if not installed then
        os.rename(backupPath, scriptPath)
        updateState.downloading = false
        removeUpdateTemp(path)
        updaterMessage('Не удалось установить обновление; исходный файл восстановлен.', 0xFF7777)
        print('[PoliceHelper] ' .. tostring(installError))
        return
    end

    updateState.downloading = false
    updateState.deadline = 0.0
    updateState.tempPath = ''
    updaterMessage('Версия ' .. latestVersion .. ' установлена. Перезагрузка скрипта...', 0x77FF77)
    lua_thread.create(function()
        wait(700)
        thisScript():reload()
    end)
end

function downloadUpdateScript(url, latestVersion, token)
    if not validRawGithubUrl(url) then
        updateState.downloading = false
        updaterMessage('В манифесте указана неверная RAW-ссылка на Lua.', 0xFF7777)
        return
    end

    local updatePath = thisScript().path .. '.update.tmp'
    removeUpdateTemp(updatePath)
    updateState.downloading = true
    updateState.checking = false
    updateState.event = nil
    updateState.downloadDataComplete = false
    updateState.tempPath = updatePath
    updateState.deadline = os.clock() + UPDATE_TIMEOUT_MS / 1000
    updaterMessage('Загрузка версии ' .. latestVersion .. '...')
    local ok, downloadId = pcall(downloadUrlToFile, updateUrl(url), updatePath, function(_, status)
        if token ~= updateState.token then return end
        if status == downloadStatus.STATUS_ENDDOWNLOADDATA then
            updateState.downloadDataComplete = true
        elseif status == downloadStatus.STATUSEX_ENDDOWNLOAD then
            queueUpdaterEvent('script', token, updatePath, latestVersion)
        end
    end)
    if not ok or not downloadId then
        updateState.downloading = false
        updateState.deadline = 0.0
        updateState.tempPath = ''
        removeUpdateTemp(updatePath)
        updaterMessage('Не удалось запустить загрузку обновления.', 0xFF7777)
        print('[PoliceHelper] ' .. tostring(downloadId))
    end
end

function checkForPoliceHelperUpdate(verbose)
    updateState.verbose = verbose == true
    if UPDATE_MANIFEST_URL == '' then
        updaterMessage('Проверка обновлений пока недоступна.', 0xFFFF77)
        return
    end
    if not validRawGithubUrl(UPDATE_MANIFEST_URL) then
        updaterMessage('Проверка обновлений временно недоступна.', 0xFF7777)
        return
    end
    if updateState.checking or updateState.downloading then
        updaterMessage('Проверка или загрузка уже выполняется.')
        return
    end

    updateState.token = updateState.token + 1
    local token = updateState.token
    local manifestPath = thisScript().path .. '.version.tmp'
    removeUpdateTemp(manifestPath)
    updateState.checking = true
    updateState.event = nil
    updateState.tempPath = manifestPath
    updateState.deadline = os.clock() + UPDATE_TIMEOUT_MS / 1000
    updaterMessage('Проверка обновления...')
    local ok, downloadId = pcall(downloadUrlToFile, updateUrl(UPDATE_MANIFEST_URL), manifestPath, function(_, status)
        if token ~= updateState.token or status ~= downloadStatus.STATUSEX_ENDDOWNLOAD then return end
        queueUpdaterEvent('manifest', token, manifestPath)
    end)
    if not ok or not downloadId then
        updateState.checking = false
        updateState.deadline = 0.0
        updateState.tempPath = ''
        removeUpdateTemp(manifestPath)
        updaterMessage('Не удалось запустить проверку обновления.', 0xFF7777)
        print('[PoliceHelper] ' .. tostring(downloadId))
        return
    end
end

function processUpdaterMainThread()
    if updateState.manualCheckRequested then
        updateState.manualCheckRequested = false
        checkForPoliceHelperUpdate(true)
    end

    if updateState.downloadRequest then
        local request = updateState.downloadRequest
        updateState.downloadRequest = nil
        updateState.verbose = true
        downloadUpdateScript(request.url, request.version, request.token)
    end

    if updateState.deadline > 0 and os.clock() >= updateState.deadline
        and (updateState.checking or updateState.downloading)
    then
        updateState.token = updateState.token + 1
        updateState.checking = false
        updateState.downloading = false
        updateState.downloadDataComplete = false
        updateState.event = nil
        updateState.deadline = 0.0
        removeUpdateTemp(updateState.tempPath)
        updateState.tempPath = ''
        updaterMessage('Время ожидания обновления истекло.', 0xFF7777)
        return
    end

    local event = updateState.event
    if not event then return end
    updateState.event = nil
    if event.token ~= updateState.token then
        removeUpdateTemp(event.path)
        return
    end

    if event.kind == 'script' then
        updateState.deadline = 0.0
        if not updateState.downloadDataComplete then
            updateState.downloading = false
            updateState.tempPath = ''
            removeUpdateTemp(event.path)
            updaterMessage('Обновление не установлено: загрузка файла не была завершена.', 0xFF7777)
            return
        end
        updateState.downloadDataComplete = false
        installDownloadedUpdate(event.path, event.version)
        return
    end

    if event.kind == 'manifest' then
        updateState.checking = false
        updateState.deadline = 0.0
        updateState.tempPath = ''
        local file = io.open(event.path, 'rb')
        if not file then
            updaterMessage('Не удалось прочитать манифест обновления.', 0xFF7777)
            return
        end
        local jsonText = file:read('*a') or ''
        file:close()
        removeUpdateTemp(event.path)
        jsonText = jsonText:gsub('^\239\187\191', '')
        local decoded, manifest = pcall(decodeJson, jsonText)
        if not decoded or type(manifest) ~= 'table' then
            updaterMessage('GitHub вернул некорректный манифест обновления.', 0xFF7777)
            return
        end
        local latest = tostring(manifest.latest or '')
        if not releaseVersionKey(latest) or type(manifest.updateurl) ~= 'string' then
            updaterMessage('В манифесте нужны поля latest и updateurl.', 0xFF7777)
            return
        end
        if latest == LOCAL_VERSION then
            updaterMessage('Установлена актуальная версия ' .. LOCAL_VERSION .. '.', 0x77FF77)
            return
        end
        if not isReleaseVersionNewer(latest, LOCAL_VERSION) then
            updaterMessage('Локальная версия новее опубликованной: ' .. LOCAL_VERSION .. '.', 0x77FF77)
            return
        end
        pendingUpdateVersion = latest
        pendingUpdateUrl = manifest.updateurl
        updateConfirm[0] = true
    end
end

familyReservedTags = {
    V = true, J = true, JN = true, G = true, P = true, R = true, RN = true,
    F = true, FN = true, D = true, L = true, A = true, I = true, S = true,
    LS = true, SF = true, LV = true, PC = true, TV = true,
    ['Тел'] = true, ['Стол'] = true, ['ТВ центр'] = true, ['ТВ-центр'] = true,
    ['Радио ЛС'] = true, ['Радио СФ'] = true, ['Радио ЛВ'] = true,
    ['Всем постам'] = true, ['Ошибка'] = true, ['Диспетчер'] = true,
    SIGNAL = true, BANK = true, PVP = true, Admin = true, GunGame = true
}

detectedFamilyTags = detectedFamilyTags or {}

-- Название семьи определяется автоматически по однозначному семейному сообщению
-- или по структуре семейного чата. После определения скрываются все сообщения
-- с тем же первым префиксом, включая уведомления шкафа, кассы и состава.
function isFamilyMessage(clean)
    local tag, remainder = tostring(clean or ''):match('^%[([^%[%]]+)%]%s+(.+)$')
    if not tag or familyReservedTags[tag] then return false end
    if detectedFamilyTags[tag] then return true end

    local lowered = lowerCp1251(' ' .. remainder)
    local explicitFamily = lowered:find(' в семью', 1, true)
        or lowered:find(' семью', 1, true)
        or lowered:find(' из семьи', 1, true)
        or lowered:find(' семьи', 1, true)
        or lowered:find(' семье', 1, true)
        or lowered:find(' семейн', 1, true)
        or lowered:find(' начал исполнять контракт', 1, true)
        or lowered:find(' выполнил контракт', 1, true)

    -- Системные сообщения семьи могут не содержать ник в формате Nick_Name.
    if explicitFamily then
        detectedFamilyTags[tag] = true
        return true
    end

    -- Новый формат: [СЕМЬЯ] [РАНГ ИЗ НЕСКОЛЬКИХ СЛОВ] Nick_Name: сообщение.
    local afterBracketRank = remainder:match('^%[[^%[%]]+%]%s+(.+)$')
    if afterBracketRank then
        local nickname = trim(afterBracketRank:match('^([^:]+):') or '')
        if nickname:find('_', 1, true) and nickname:match('^[A-Za-z0-9_]+$') then
            detectedFamilyTags[tag] = true
            return true
        end
    end

    -- Формат без отображаемого ранга: [СЕМЬЯ] Nick_Name: сообщение.
    local directNickname = trim(remainder:match('^([^%s:]+):') or '')
    if directNickname:find('_', 1, true)
        and directNickname:match('^[A-Za-z0-9_]+$')
    then
        detectedFamilyTags[tag] = true
        return true
    end

    -- Старый формат: [СЕМЬЯ] Ранг Nick_Name: сообщение.
    local speaker = trim(remainder:match('^([^:]+):') or '')
    local rank, nickname = speaker:match('^(.+)%s+([^%s]+)$')
    if rank and nickname and nickname:find('_', 1, true)
        and nickname:match('^[A-Za-z0-9_]+$')
    then
        detectedFamilyTags[tag] = true
        return true
    end

    return false
end

-- Подтверждение сопоставляется с нашей командой, персонажем и коротким сроком ожидания.
function sendConfirmedServiceCommand(key, command)
    serviceCommandPending[key] = nil
    local ok, found, id = pcall(sampGetPlayerIdByCharHandle, PLAYER_PED)
    if not ok or not found or type(id) ~= 'number' then
        notify('Не удалось определить собственный ID.')
        return
    end
    local nameOk, nickname = pcall(sampGetPlayerNickname, id)
    if not nameOk or type(nickname) ~= 'string' or nickname == '' then
        notify('Не удалось определить собственный никнейм.')
        return
    end
    serviceCommandPending[key] = { id = id, nickname = nickname, expires = os.clock() + 8.0 }
    local sent, err = pcall(sampSendChat, command)
    if not sent then
        serviceCommandPending[key] = nil
        notify('Не удалось отправить серверную команду.')
        print('[PoliceHelper] Ошибка отправки служебной команды: ' .. tostring(err))
    end
end

function handleServiceCommandConfirmation(clean)
    if clean:match('^Connecting to%s+') then serviceCommandPending = {}; return end
    for key, pending in pairs(serviceCommandPending) do
        if os.clock() > pending.expires then serviceCommandPending[key] = nil end
    end
    local form = serviceCommandPending.form
    if form then
        local nickname, id, action = clean:match(' ([%w_]+)%[(%d+)%]%s+(.+)$')
        if nickname == form.nickname and tonumber(id) == form.id then
            local enabled = action == 'включил возможность менять форму' or action == 'включила возможность менять форму'
            local disabled = action == 'отключил возможность менять форму' or action == 'отключила возможность менять форму'
            if enabled or disabled then
                serviceCommandPending.form = nil
                if enabled then
                    sampSendChat(configuredRoleplayLine('form_on', 1, '/me открыл служебную раздевалку через панель планшета'))
                else
                    sampSendChat(configuredRoleplayLine('form_off', 1, '/me закрыл доступ к служебной раздевалке через планшет'))
                end
            end
        end
    end
    local gps = serviceCommandPending.gps_clear
    if gps then
        local nickname, reason = clean:match('^Вы сняли розыск с ([%w_]+) по причине:%s*(.+)$')
        if nickname == gps.nickname and trim(reason or ''):gsub('%.$', '') == 'GPS OFF' then
            serviceCommandPending.gps_clear = nil
            sampSendChat(configuredRoleplayLine('gpsoff', 1, '/me отключил GPS-трекер и удалил служебную отметку из базы МВД'))
        end
    end
end

function handleServerMessageEvent(color, text)
    local clean = trim(stripColorCodes(text))
    handleSosLocationMessage(clean)
    handleServiceCommandConfirmation(clean)
    if type(handleLegalConnectionMessage) == 'function' then handleLegalConnectionMessage(clean) end
    if type(policeHelperConfirmText) == 'function' then policeHelperConfirmText(clean) end

    local callerPhone = clean:match('^Входящий звонок%s*|%s*Номер:%s*(%d+)')
    if callerPhone then
        lastIncomingPhone = callerPhone
        incomingCallUntil = os.clock() + 30.0
    end
    local smsPhone = clean:match('^SMS:.-|%s*Отправитель:.-%[т%.(%d+)%]')
    if smsPhone then lastIncomingPhone = smsPhone end
    if clean:find('Используйте /p чтобы ответить или /h чтобы отклонить вызов', 1, true) then
        incomingCallUntil = os.clock() + 30.0
        local changed = tostring(text)
            :gsub('({%x%x%x%x%x%x})/p', '%1Y', 1)
            :gsub('({%x%x%x%x%x%x})/h', '%1N', 1)
        return { color, changed }
    end

    if departmentDoorPending then
        if os.clock() > departmentDoorPendingUntil then
            departmentDoorPending = false
        elseif clean == 'Вы открыли дверь' or clean == 'Вы закрыли дверь' then
            departmentDoorPending = false
            departmentDoorPendingUntil = 0.0
            if clean == 'Вы открыли дверь' then
                sampSendChat(configuredRoleplayLine('door_open', 1, '/me нажал кнопку на служебной панели управления и открыл дверь'))
            else
                sampSendChat(configuredRoleplayLine('door_close', 1, '/me нажал кнопку на служебной панели управления и закрыл дверь'))
            end
        end
    end

    local confirmationText = clean:gsub('\194\160', ' '):gsub('\160', ' '):gsub('[\t ]+', ' ')

    if cuffRpPendingId >= 0 then
        if os.clock() > cuffRpPendingUntil then
            cuffRpPendingId = -1
            cuffRpPendingNickname = ''
            cuffRpPendingActor = ''
            cuffRpPendingUntil = 0.0
        else
            local ownActionText = confirmationText:gsub('_', ' ')
            local cuffConfirmed = cuffRpPendingActor ~= ''
                and (ownActionText:find(' ' .. cuffRpPendingActor .. ' надел на ', 1, true)
                    or ownActionText:find(' ' .. cuffRpPendingActor .. ' надела на ', 1, true))
                and cuffRpPendingNickname ~= ''
                and ownActionText:find(' на ' .. cuffRpPendingNickname .. ' наручники', 1, true)
                and ownActionText:find(' наручники', 1, true)
            if cuffConfirmed then
                cuffRpPendingId = -1
                cuffRpPendingNickname = ''
                cuffRpPendingActor = ''
                cuffRpPendingUntil = 0.0
                runSequence('Наручники после подтверждения', {
                    configuredRoleplayLine('cuff', 1, '/me снял наручники с поясного держателя и раскрыл фиксирующий механизм'),
                    configuredRoleplayLine('cuff', 2, '/me зафиксировал наручники на запястьях задержанного')
                })
            end
        end
    end

    if uncuffRpPending then
        if os.clock() > uncuffRpPendingUntil then
            uncuffRpPending = false
            uncuffRpPendingNickname = ''
            uncuffRpPendingActor = ''
            uncuffRpPendingUntil = 0.0
        else
            local ownActionText = confirmationText:gsub('_', ' ')
            local uncuffConfirmed = uncuffRpPendingActor ~= ''
                and (ownActionText:find(' ' .. uncuffRpPendingActor .. ' снял с ', 1, true)
                    or ownActionText:find(' ' .. uncuffRpPendingActor .. ' сняла с ', 1, true))
                and uncuffRpPendingNickname ~= ''
                and ownActionText:find(' с ' .. uncuffRpPendingNickname .. ' наручники', 1, true)
                and ownActionText:find(' наручники', 1, true)
            if uncuffConfirmed then
                uncuffRpPending = false
                uncuffRpPendingNickname = ''
                uncuffRpPendingActor = ''
                uncuffRpPendingUntil = 0.0
                runSequence('Снятие наручников после подтверждения', {
                    configuredRoleplayLine('uncuff', 1, '/me достал ключ и открыл фиксирующий механизм наручников'),
                    configuredRoleplayLine('uncuff', 2, '/me снял наручники с рук задержанного и закрепил их на поясе')
                })
            end
        end
    end

    if holdRpPendingId >= 0 then
        if os.clock() > holdRpPendingUntil then
            holdRpPendingId = -1
            holdRpPendingNickname = ''
            holdRpPendingUntil = 0.0
        else
            if confirmationText:find('Вы ведёте за собой ', 1, true) == 1 then
                holdRpPendingId = -1
                holdRpPendingNickname = ''
                holdRpPendingUntil = 0.0
                sampSendChat(configuredRoleplayLine('hold', 1, '/me аккуратно взял задержанного под руку и повёл за собой'))
            end
        end
    end

    if detentionRpPendingId >= 0 then
        if os.clock() > detentionRpPendingUntil then
            detentionRpPendingId = -1
            detentionRpPendingNickname = ''
            detentionRpPendingUntil = 0.0
        else
            local detentionNickname = confirmationText:match(
                '^([%w_]+) попал[аи]? в Ваше поле зрения%.'
            )
            if detentionNickname
                and (detentionRpPendingNickname == '' or detentionNickname == detentionRpPendingNickname)
            then
                detentionRpPendingId = -1
                detentionRpPendingNickname = ''
                detentionRpPendingUntil = 0.0
                sampSendChat(configuredRoleplayLine(
                    'y', 1, '/me активировал режим задержания в служебном планшете'
                ))
            end
        end
    end

    if putplRpPending then
        if os.clock() > putplRpPendingUntil then
            putplRpPending = false
            putplRpPendingActor = ''
            putplRpPendingUntil = 0.0
        else
            local ownActionText = confirmationText:gsub('_', ' ')
            local putplConfirmed = putplRpPendingActor ~= ''
                and (ownActionText:find(' ' .. putplRpPendingActor .. ' посадил ', 1, true)
                    or ownActionText:find(' ' .. putplRpPendingActor .. ' посадила ', 1, true))
                and ownActionText:find(' в машину', 1, true)
            if putplConfirmed then
                putplRpPending = false
                putplRpPendingActor = ''
                putplRpPendingUntil = 0.0
                sampSendChat(configuredRoleplayLine('putpl', 2, '/me придерживая задержанного, помог ему сесть на заднее сиденье'))
                putplRpClosePending = true
                putplRpCloseAt = os.clock() + math.max(0, delayMs[0]) / 1000.0
            end
        end
    end

    if pullRpPendingId >= 0 then
        if os.clock() > pullRpPendingUntil then
            pullRpPendingId = -1
            pullRpPendingNickname = ''
            pullRpPendingActor = ''
            pullRpPendingUntil = 0.0
            pullRpPendingFirst = ''
            pullRpPendingSecond = ''
        else
            local ownActionText = confirmationText:gsub('_', ' ')
            local actorConfirmed = pullRpPendingActor ~= ''
                and (ownActionText:find(pullRpPendingActor .. ' вытащил ', 1, true)
                    or ownActionText:find(pullRpPendingActor .. ' вытащила ', 1, true))
            local targetConfirmed = pullRpPendingNickname ~= ''
                and ownActionText:find(' ' .. pullRpPendingNickname .. ' из транспорта', 1, true)
            if actorConfirmed and targetConfirmed then
                local firstLine = pullRpPendingFirst
                local secondLine = pullRpPendingSecond
                pullRpPendingId = -1
                pullRpPendingNickname = ''
                pullRpPendingActor = ''
                pullRpPendingUntil = 0.0
                pullRpPendingFirst = ''
                pullRpPendingSecond = ''
                sampSendChat(configuredRoleplayLine('pull', 1, firstLine))
                if secondLine ~= '' then
                    lua_thread.create(function()
                        wait(math.max(0, delayMs[0]))
                        if isSampAvailable() then
                            sampSendChat(configuredRoleplayLine('pull', 2, secondLine))
                        end
                    end)
                end
            end
        end
    end

    if autoReportDamager[0] then
        local killerNickname, killerId = clean:match('^%[Всем постам%]%s+([%w_]+)%[(%d+)%]%s+совершил убийство%s+|')
        killerId = tonumber(killerId)
        if killerId then
            local now = os.clock()
            local recent = damagerKillTimes[killerId] or {}
            local fresh = {}
            for _, killAt in ipairs(recent) do
                if now - killAt <= 15.0 then fresh[#fresh + 1] = killAt end
            end
            fresh[#fresh + 1] = now
            damagerKillTimes[killerId] = fresh

            local twoVeryFast = #fresh >= 2 and now - fresh[#fresh - 1] <= 6.0
            local threeInWindow = #fresh >= 3
            if (twoVeryFast or threeInWindow) and now - lastAutoReportAt >= 15.0 then
                lastDamagerReportAt = now
                lastAutoReportAt = now
                damagerKillTimes[killerId] = {}
                lua_thread.create(function()
                    wait(100)
                    sampSendChat('/re Дамагер! Ник: ' .. killerNickname .. '. ID: ' .. killerId)
                end)
            end
        end
    end

    local sharedCaseId, sharedCaseName, sharedActor = clean:match(
        '^На дисплее данные и координаты дела №(%d+)%s*[%-%–]%s*(.-)%.%s*%(([%w_]+)%)$'
    )
    if not sharedCaseId then
        sharedActor, sharedCaseName, sharedCaseId = clean:match(
            '^([%w_]+) потянулся к планшету, ввёл запрос:%s*(.-)%s*%[Дело №(%d+)%]%.?$'
        )
    end
    sharedCaseId = tonumber(sharedCaseId)
    if sharedCaseId
        and sampIsPlayerConnected(sharedCaseId)
        and isTrackingOfferFromOtherOfficer(sharedActor)
    then
        sharedTrackingOfferId = sharedCaseId
        sharedTrackingOfferName = trim(sharedCaseName)
        sharedTrackingOfferUntil = os.clock() + 12.0
        notify('Сотрудник получил координаты дела №' .. sharedCaseId .. ' – '
            .. sharedTrackingOfferName .. '. Y – отслеживать, N – отказаться.')
    end

    local detectedName, detectedId = clean:match('^(.+)%[(%d+)%] был обнаружен в районе%s+.+$')
    detectedId = tonumber(detectedId)
    if detectedId then
        if detectedId == sharedTrackingSwitchId then
            sharedTrackingSwitchId = -1
            sharedTrackingSwitchName = ''
            sharedTrackingSwitchUntil = 0.0
        end
        clearTrackedTarget(true)
        trackedTargetId = detectedId
        trackedTargetNickname = trim(detectedName)
        trackingConfirmed = true
        trackedMapId, trackedNameTextdrawId, trackedPointTextdrawId = -1, -1, -1
        trackedMapNextSearch = 0
        trackedMapSearchUntil = os.clock() + 20.0
        lua_thread.create(function()
            wait(150)
            if isSampAvailable() and trackedTargetId == detectedId and trackingConfirmed then
                sendRawRpCommand('/me вносит данные в бортовой компьютер, получает результат на дисплей.')
                wait(math.max(0, delayMs[0]))
                if trackedTargetId == detectedId and trackingConfirmed then
                    local displayName = trim(detectedName):gsub('_', ' ')
                    sampSendChat('/do На дисплее данные и координаты дела №' .. detectedId .. ' - ' .. displayName .. '.')
                end
            end
        end)
    elseif clean == 'Система слежения отключена' then
        clearTrackedTarget(true)
        if sharedTrackingSwitchId >= 0 and os.clock() <= sharedTrackingSwitchUntil
            and sampIsPlayerConnected(sharedTrackingSwitchId)
        then
            sharedTrackingOfferId = sharedTrackingSwitchId
            sharedTrackingOfferName = sharedTrackingSwitchName
            sharedTrackingOfferUntil = os.clock() + 12.0
            notify('Прежнее отслеживание отключено. Y – отслеживать дело №'
                .. sharedTrackingOfferId .. ' – ' .. sharedTrackingOfferName .. ', N – отказаться.')
        end
        sharedTrackingSwitchId = -1
        sharedTrackingSwitchName = ''
        sharedTrackingSwitchUntil = 0.0
    end

    local sosGpsId, sosWantedLevel = confirmationText:match(
        '^Вы объявили .+ в розыск%. Причина:%s*SOS! GPS:%s*(%d+)%. Текущий уровень розыска%s+(%d+)$'
    )
    sosGpsId, sosWantedLevel = tonumber(sosGpsId), tonumber(sosWantedLevel)
    if sosEscalationActive and sosEscalationAwaiting
        and sosGpsId == sosEscalationId and sosWantedLevel
    then
        sosEscalationAwaiting = false
        sosEscalationConfirmed = sosEscalationConfirmed + 1
        sosEscalationExpiresAt = 0.0
        if sosEscalationConfirmed >= 2 or sosWantedLevel >= 6 then
            sosEscalationActive = false
            sosEscalationId = -1
            sosEscalationConfirmed = 0
            sosEscalationNextAt = 0.0
        else
            sosEscalationNextAt = os.clock() + math.max(0.25, delayMs[0] / 1000.0)
        end
    end

    local wantedConfirmed = confirmationText:match('^Вы объявили .+ в розыск%.') ~= nil
    if wantedConfirmed and pendingWantedTargetId >= 0
        and os.clock() <= pendingWantedExpiresAt
    then
        sampSendChat(configuredRoleplayLine(
            pendingWantedRoleplayKey, 1, pendingWantedRoleplayFallback
        ))
        pendingWantedTargetId = -1
        pendingWantedTargetNickname = ''
        pendingWantedExpiresAt = 0.0
        pendingWantedReason = ''
        pendingWantedRetryUsed = false
        pendingWantedRoleplayKey = 'su'
        pendingWantedRoleplayFallback = '/me внёс данные подозреваемого в базу розыска'
    end

    local currentWanted, allowedIncrease = clean:match(
        '^Сейчас у игрока (%d+) уров%S* розыска%. Вы можете его увеличить на (%d+)$'
    )
    allowedIncrease = tonumber(allowedIncrease)
    if currentWanted and allowedIncrease and allowedIncrease > 0
        and pendingWantedTargetId >= 0
        and pendingWantedReason ~= ''
        and not pendingWantedRetryUsed
        and os.clock() <= pendingWantedExpiresAt
    then
        pendingWantedRetryUsed = true
        local retryId = pendingWantedTargetId
        local retryReason = pendingWantedReason
        local retryStars = allowedIncrease
        lua_thread.create(function()
            wait(50)
            if isSampAvailable() and pendingWantedTargetId == retryId
                and os.clock() <= pendingWantedExpiresAt
            then
                sampSendChat('/su ' .. retryId .. ' ' .. retryStars .. ' ' .. retryReason)
            end
        end)
    end

    if hideAds[0] then
        local isAdvertisement = clean:find('| Отправил ', 1, true)
            and clean:match('%[%d+%]%s*%(тел%.%s*[^%)]+%)%s*$')
        local isAdvertisementCheck = clean:match('^Объявление проверил сотрудник СМИ%s+.+$')
        if isAdvertisement or isAdvertisementCheck then return false end
    end

    if hideVChannel[0] and clean:match('^%[V%]%s') then return false end
    if hideJobChannels[0]
        and (clean:match('^%[J%]%s') or clean:match('^%(%(%s*%[JN%]%s'))
    then
        return false
    end
    if hideGChannel[0] and clean:match('^%[G%]%s') then return false end
    if hidePChannel[0] and clean:match('^%[P%]%s') then return false end
    if hideGovNews[0] and clean:match('^Гос%. новости:%s') then return false end
    if hideFamilyChat[0] and isFamilyMessage(clean) then return false end

    if resetAfterMask[0]
        and clean:find('Ваше месторасположение на GPS скрыто на 10 минут', 1, true)
    then
        lua_thread.create(function()
            wait(100)
            sampSendChat('/reset')
        end)
    end

    -- Успех отслеживается пассивно: запрос не блокирует команды и не занимает очередь.
    if maskRpUntil > 0 and policeHelperTextMilliseconds() <= maskRpUntil then
        if clean == 'Вы надели маску' or clean:match('^Вы надели маску[%.!]') then
            maskRpUntil = 0.0
            lua_thread.create(function()
                wait(0)
                sampSendChat(configuredRoleplayLine('mask', 1, '/me достал маску из кармана и надел её на лицо'))
            end)
        elseif clean == 'У Вас нет с собой маски' then
            maskRpUntil = 0.0
        end
    end

    if clean == 'Вы сняли маску' then
        if unmaskRpPending then
            unmaskRpPending = false
            lua_thread.create(function()
                wait(100)
                sampSendChat(configuredRoleplayLine('unmask', 1, '/me аккуратно снял маску с лица человека напротив'))
            end)
        else
            lua_thread.create(function()
                wait(100)
                sampSendChat(configuredRoleplayLine('mask_off', 1, '/me снял маску с лица и убрал её в карман'))
            end)
        end
    elseif unmaskRpPending then
        if clean == 'Игрок слишком далеко' or clean:find('Используйте /unmask', 1, true) then
            unmaskRpPending = false
        end
    end

    if healmeRpUntil > 0 and policeHelperTextMilliseconds() <= healmeRpUntil
        and (clean == 'Вы использовали аптечку' or clean:match('^Вы использовали аптечку[%.!]'))
    then
        healmeRpUntil = 0.0
        lua_thread.create(function()
            wait(0)
            sampSendChat(configuredRoleplayLine('healme', 1, '/me достал аптечку и оказал себе первую помощь'))
        end)
    end

    if autoEat[0]
        and clean:find('Используйте /eat чтобы поесть или /put чтобы положить поднос с едой', 1, true)
        and os.clock() - lastAutoEatAt >= 3.0
    then
        lastAutoEatAt = os.clock()
        lua_thread.create(function()
            wait(1000)
            sampSendChat('/eat')
        end)
    end

    if clean == 'Последнее ограждение убрано' then
        lua_thread.create(function()
            wait(100)
            sampSendChat('/me убрал последнее служебное ограждение в багажник')
        end)
    elseif clean == 'Все ограждения убраны' then
        lua_thread.create(function()
            wait(100)
            sampSendChat('/me собрал все служебные ограждения и убрал их в багажник')
        end)
    end
    if clean:find('Доступны ежедневные, еженедельные и сезонные задания:', 1, true)
        and clean:find('/tasks', 1, true)
        and not profileManual[0]
        and os.clock() - lastStatsRequest > 30
    then
        lastStatsRequest = os.clock()
        lua_thread.create(function()
            wait(1000)
            if not isSampAvailable() then return end
            statsRequestPending = true
            sampSendChat('/st')
            wait(10000)
            statsRequestPending = false
        end)
    end

    if whiteMaskedChatIds[0] and clean:match('^%- .- %([^%)]+%)(%[%d+%])$') then
        local recolored, count = text:gsub('(%[%d+%])%s*$', '{FFFFFF}%1', 1)
        if count > 0 then return { color, recolored } end
    end

end

local function requestStatsNow()
    if profileManual[0] then
        notify('Для обновления через /st выберите автоматический режим профиля.')
        return
    end
    if statsRequestPending then
        notify('Запрос статистики уже выполняется.')
        return
    end
    statsRequestPending = true
    lastStatsRequest = os.clock()
    sampSendChat('/st')
    lua_thread.create(function()
        wait(10000)
        statsRequestPending = false
    end)
end

function sampev.onServerMessage(color, text)
    return safeEventCall('сообщения сервера', handleServerMessageEvent, color, text)
end

function handleAutoMaskTimer(x, y, text)
    if not autoMaskRenew[0] then return end
    if trim(stripColorCodes(text)) ~= '00:03' then return end
    x, y = tonumber(x), tonumber(y)
    if not x or not y or math.abs(x - 37.0) > 2.0 or math.abs(y - 306.0) > 2.0 then return end
    local now = os.time()
    if now - lastAutoMaskRenewAt < 15 then return end
    lastAutoMaskRenewAt = now
    commandMask()
end

function handleAutoMaskTextdrawUpdate(id, text)
    if not autoMaskRenew[0] or trim(stripColorCodes(text)) ~= '00:03' then return end
    if not sampTextdrawIsExists(id) then return end
    local x, y = sampTextdrawGetPos(id)
    handleAutoMaskTimer(x, y, text)
end

function sampev.onShowTextDraw(id, textdraw)
    return safeEventCall('появления таймера маски', function()
        if type(textdraw) ~= 'table' or type(textdraw.position) ~= 'table' then return end
        handleAutoMaskTimer(textdraw.position.x, textdraw.position.y, textdraw.text)
    end)
end

function sampev.onTextDrawSetString(id, text)
    return safeEventCall('обновления таймера маски', handleAutoMaskTextdrawUpdate, id, text)
end

local function handleAutoEquipment(dialogId, style, button1, text)
    if not autoEquipment[0] or style ~= 5 then return end

    local cleanButton = trim(stripColorCodes(button1))
    local cleanText = stripColorCodes(text):gsub('\r', '')
    if cleanButton ~= 'Взять'
        or not cleanText:find('Оружие', 1, true)
        or not cleanText:find('Кол%-во')
    then
        return
    end

    local now = os.clock()
    if now - equipmentLastDialogAt > 5.0 then equipmentAttempted = {} end
    equipmentLastDialogAt = now

    local dialogItems = {}
    local knownListChanged = false
    local rowIndex = -1
    local headerPassed = false
    for line in (cleanText .. '\n'):gmatch('(.-)\n') do
        line = trim(line)
        if not headerPassed then
            if line:find('Оружие', 1, true) and line:find('Кол%-во') then headerPassed = true end
        elseif line ~= '' then
            rowIndex = rowIndex + 1
            local itemName = trim(line:match('^%d+%.%s*([^\t]+)') or '')
            if itemName ~= '' then
                dialogItems[#dialogItems + 1] = { name = itemName, row = rowIndex }
                if not equipmentKnownSet[itemName] then
                    equipmentKnownSet[itemName] = true
                    equipmentKnown[#equipmentKnown + 1] = itemName
                    equipmentChoices[itemName] = new.bool(false)
                    knownListChanged = true
                end
            end
        end
    end
    if knownListChanged then saveConfig() end

    local selectedItems = {}
    for _, dialogItem in ipairs(dialogItems) do
        local choice = equipmentChoices[dialogItem.name]
        if choice and choice[0] and not equipmentAttempted[dialogItem.name] then
            selectedItems[#selectedItems + 1] = dialogItem
        end
    end
    if #selectedItems == 0 then return end

    equipmentAutoToken = equipmentAutoToken + 1
    for _, selectedItem in ipairs(selectedItems) do
        equipmentAttempted[selectedItem.name] = true
        sampSendDialogResponse(dialogId, 1, selectedItem.row, '')
    end
    return true
end

function handleAutoFuel(dialogId, style, button1, text)
    if not autoFuel[0] or tonumber(style) ~= 1 then return end
    local cleanButton = trim(stripColorCodes(button1))
    local cleanText = stripColorCodes(text):gsub('\r', '')
    if cleanButton ~= 'Купить'
        or not cleanText:find('Стоимость 1 л топлива:', 1, true)
        or not cleanText:find('Оставшийся запас на АЗС:', 1, true)
        or not cleanText:find('Укажите количество литров для покупки:', 1, true)
    then
        return
    end

    local liters = tonumber(cleanText:match('В ваш транспорт поместится ещё%s+(%d+)%s+л'))
    if not liters or liters < 1 or os.clock() - lastAutoFuelAt < 1.0 then return end
    lastAutoFuelAt = os.clock()
    local sent = pcall(sampSendDialogResponse, dialogId, 1, 65535, tostring(liters))
    if sent then return true end
end

function handleCleanOnlineDialog(title, text)
    local cleanTitle = trim(stripColorCodes(title))
    local cleanText = stripColorCodes(text):gsub('\r', '')
    if cleanTitle ~= 'Точное время' then return end

    local playedHours, playedMinutes = cleanText:match('Время в игре сегодня:%s*(%d+)%s*ч%s*(%d+)%s*мин')
    local afkHours, afkMinutes = cleanText:match('AFK за сегодня:%s*(%d+)%s*ч%s*(%d+)%s*мин')
    playedHours, playedMinutes = tonumber(playedHours), tonumber(playedMinutes)
    afkHours, afkMinutes = tonumber(afkHours), tonumber(afkMinutes)
    if not playedHours or not playedMinutes or not afkHours or not afkMinutes then return end

    local cleanMinutes = math.max(0, playedHours * 60 + playedMinutes - afkHours * 60 - afkMinutes)
    local signature = table.concat({ playedHours, playedMinutes, afkHours, afkMinutes }, ':')
    if signature == lastCleanOnlineSignature then return end
    lastCleanOnlineSignature = signature
    notify(string.format('Чистый онлайн сегодня: %d ч %d мин.',
        math.floor(cleanMinutes / 60), cleanMinutes % 60))
end

function handleShowDialogEvent(dialogId, style, title, button1, button2, text)
    if handleAutoEquipment(dialogId, style, button1, text) then return false end
    if handleAutoFuel(dialogId, style, button1, text) then return false end
    handleCleanOnlineDialog(title, text)
    if profileManual[0] or not statsRequestPending then return end

    local cleanTitle = trim(stripColorCodes(title))
    local cleanText = stripColorCodes(text)
    if cleanTitle ~= 'Статистика игрока'
        or not cleanText:find('Подразделение:', 1, true)
        or not cleanText:find('Должность:', 1, true)
    then
        return
    end

    local department = trim(cleanText:match('Подразделение:%s*([^\r\n]+)'))
    local rank = trim(cleanText:match('Должность:%s*([^\r\n]+)'))
    if department ~= '' then setBuffer(departmentBuf, ffi.sizeof(departmentBuf), department) end
    if rank ~= '' then setBuffer(rankBuf, ffi.sizeof(rankBuf), rank) end

    statsRequestPending = false
    profileLoadedAutomatically = department ~= '' and rank ~= ''
    saveConfig()
    addLog('Профиль автоматически получен из /st')
    notify('Профиль определён: ' .. department .. ' | ' .. rank .. '.')
    return false
end

function sampev.onShowDialog(dialogId, style, title, button1, button2, text)
    return safeEventCall('диалога сервера', handleShowDialogEvent, dialogId, style, title, button1, button2, text)
end

local function getLocalName()
    local ok, id = sampGetPlayerIdByCharHandle(PLAYER_PED)
    if not ok then return 'Сотрудник МВД' end
    local success, name = pcall(sampGetPlayerNickname, id)
    if not success or not name or name == '' then return 'Сотрудник МВД' end
    return name:gsub('_', ' ')
end

local function getPlayerById(value)
    local id = tonumber(value)
    if not id or id < 0 or id > 999 then
        return nil, nil, 'Укажите корректный ID игрока.'
    end
    local selfOk, selfId = sampGetPlayerIdByCharHandle(PLAYER_PED)
    local isSelf = selfOk and selfId == id
    if isSelf then return id, getLocalName() end
    if not isSelf and type(sampIsPlayerConnected) == 'function' and not sampIsPlayerConnected(id) then
        return nil, nil, 'Игрок с ID ' .. id .. ' не найден.'
    end
    local ok, name = pcall(sampGetPlayerNickname, id)
    if not ok or not name or name == '' then
        return nil, nil, 'Игрок с ID ' .. id .. ' не найден.'
    end
    return id, name:gsub('_', ' ')
end

local function getTarget()
    return getPlayerById(targetId[0])
end

local function targetFromAim()
    local ok, ped = getCharPlayerIsTargeting(PLAYER_HANDLE)
    if not ok then
        notify('Наведите прицел на игрока и повторите.')
        return
    end
    local found, id = sampGetPlayerIdByCharHandle(ped)
    if not found then
        notify('Не удалось определить ID игрока.')
        return
    end
    targetId[0] = id
    notify('Выбран игрок: ' .. sampGetPlayerNickname(id) .. '[' .. id .. '].')
end

local function getCharVehicleSafe(ped)
    if type(isCharInAnyCar) ~= 'function' or not isCharInAnyCar(ped) then return nil end
    local ok, vehicle = pcall(storeCarCharIsInNoSave, ped)
    if not ok or not vehicle or vehicle <= 0 then return nil end
    if type(doesVehicleExist) == 'function' and not doesVehicleExist(vehicle) then return nil end
    return vehicle
end

function isTrackingOfferFromOtherOfficer(actorNickname)
    if not actorNickname or actorNickname == '' then return false end
    local selfCallOk, selfFound, selfId = pcall(sampGetPlayerIdByCharHandle, PLAYER_PED)
    if not selfCallOk or not selfFound then return false end
    local nickOk, ownNickname = pcall(sampGetPlayerNickname, selfId)
    return nickOk and ownNickname ~= nil and ownNickname ~= ''
        and ownNickname ~= actorNickname
end

local function getVehicleNameSafe(vehicle)
    if not vehicle or vehicle <= 0 then return 'неизвестный автомобиль' end
    local okModel, model = pcall(getCarModel, vehicle)
    if not okModel or not model then return 'неизвестный автомобиль' end
    if customCars[model] then return customCars[model] end
    local okName, name = pcall(getNameOfVehicleModel, model)
    if okName and name and name ~= '' then return name end
    return 'неизвестный автомобиль'
end

local function getVehicleDriverAddress(vehicle)
    if not vehicle or vehicle <= 0 then return 'Водитель автомобиля' end
    local okModel, model = pcall(getCarModel, vehicle)
    if not okModel or not model then return 'Водитель автомобиля' end
    local vehicleName = getVehicleNameSafe(vehicle)
    local upperName = vehicleName:upper()

    if policeHelperIsBicycleModel(model) then
        return vehicleName ~= 'неизвестный автомобиль'
            and ('Водитель велосипеда ' .. vehicleName) or 'Водитель велосипеда'
    end
    if motorcycleModels[model] then
        return vehicleName ~= 'неизвестный автомобиль'
            and ('Водитель мотоцикла ' .. vehicleName) or 'Водитель мотоцикла'
    end
    if busModels[model] or upperName == 'BUS' or upperName == 'COACH' then
        return 'Водитель автобуса'
    end
    if taxiModels[model] or upperName == 'TAXI' or upperName == 'CABBIE' then
        return 'Водитель такси'
    end
    if boatModels[model] then
        return vehicleName ~= 'неизвестный автомобиль'
            and ('Водитель катера ' .. vehicleName) or 'Водитель катера'
    end
    if helicopterModels[model] then
        return vehicleName ~= 'неизвестный автомобиль'
            and ('Пилот вертолёта ' .. vehicleName) or 'Пилот вертолёта'
    end
    if airplaneModels[model] then
        return vehicleName ~= 'неизвестный автомобиль'
            and ('Пилот самолёта ' .. vehicleName) or 'Пилот самолёта'
    end
    if trainModels[model] then return 'Машинист поезда' end
    if vehicleName == 'неизвестный автомобиль' then return 'Водитель автомобиля' end
    return 'Водитель автомобиля ' .. vehicleName
end

local function getVehicleDriverIdSafe(vehicle)
    if not vehicle or vehicle <= 0 then return nil end
    local driverOk, driver = pcall(getDriverOfCar, vehicle)
    if not driverOk or type(driver) ~= 'number' or driver <= 0 then return nil end
    local existsOk, exists = pcall(doesCharExist, driver)
    if not existsOk or not exists then return nil end
    local idCallOk, idFound, id = pcall(sampGetPlayerIdByCharHandle, driver)
    if not idCallOk or not idFound or type(id) ~= 'number' then return nil end
    return id
end

local function getVehicleMegaphoneAddress(vehicle)
    local address = getVehicleDriverAddress(vehicle)
    local driverId = getVehicleDriverIdSafe(vehicle)
    if driverId then
        address = address .. ', регистрационный номер ' .. driverId
    end
    return address
end

function getVehicleReportKind(vehicle)
    local okModel, model = pcall(getCarModel, vehicle)
    if not okModel or not model then return 'Транспорт' end
    local vehicleName = getVehicleNameSafe(vehicle):upper()
    if policeHelperIsBicycleModel(model) then return 'Велосипед' end
    if motorcycleModels[model] then return 'Мотоцикл' end
    if busModels[model] or vehicleName == 'BUS' or vehicleName == 'COACH' then return 'Автобус' end
    if taxiModels[model] or vehicleName == 'TAXI' or vehicleName == 'CABBIE' then return 'Такси' end
    if boatModels[model] then return 'Катер' end
    if helicopterModels[model] then return 'Вертолёт' end
    if airplaneModels[model] then return 'Самолёт' end
    if trainModels[model] then return 'Поезд' end
    return 'Автомобиль'
end

function getVehicleReportColor(vehicle)
    if type(getCarColours) ~= 'function' then return 'неизвестного' end
    local okColors, primaryColor = pcall(getCarColours, vehicle)
    if not okColors then return 'неизвестного' end
    return vehicleColorNames[tonumber(primaryColor)] or 'неизвестного'
end

function getVehicleRadioReport(vehicle)
    if not vehicle then return '' end
    local vehicleType = getVehicleReportKind(vehicle)
    local vehicleName = getVehicleNameSafe(vehicle)
    if vehicleName == 'неизвестный автомобиль' then vehicleName = 'неопределённой модели' end
    local colorName = getVehicleReportColor(vehicle)
    local driverId = getVehicleDriverIdSafe(vehicle)
    local numberText = driverId and (' с N-' .. driverId) or ''
    return vehicleType .. ' ' .. vehicleName .. ' ' .. colorName .. ' цвета' .. numberText .. '.'
end

local function isValidUtf8(text)
    local index, length = 1, #text
    while index <= length do
        local byte = text:byte(index)
        local extra
        if byte < 0x80 then extra = 0
        elseif byte >= 0xC2 and byte <= 0xDF then extra = 1
        elseif byte >= 0xE0 and byte <= 0xEF then extra = 2
        elseif byte >= 0xF0 and byte <= 0xF4 then extra = 3
        else return false end
        if index + extra > length then return false end
        for offset = 1, extra do
            local continuation = text:byte(index + offset)
            if continuation < 0x80 or continuation > 0xBF then return false end
        end
        index = index + extra + 1
    end
    return true
end

local function findCoordinateArea(areas, x, y, z)
    for _, area in ipairs(areas) do
        if x >= area[2] and y >= area[3] and z >= area[4]
            and x <= area[5] and y <= area[6] and z <= area[7]
        then
            return area[1]
        end
    end
end

local function getCurrentDistrict()
    local okCoords, x, y, z = pcall(getCharCoordinates, PLAYER_PED)
    if not okCoords then return nil end
    local coordinateZone = findCoordinateArea(zoneAreas, x, y, z)
    if coordinateZone and coordinateZone ~= '' then return coordinateZone end
    local okZone, zone = pcall(getNameOfZone, x, y, z)
    if not okZone or not zone or zone == '' then return nil end

    -- getNameOfZone уже возвращает готовое название. Повторный getGxtText портит его кодировку.
    zone = tostring(zone)
    if zone:find('[\128-\255]') and isValidUtf8(zone) then
        local okDecode, decoded = pcall(function() return u8:decode(zone) end)
        if okDecode and decoded and decoded ~= '' then zone = decoded end
    end
    return zone
end

local function getCurrentCity()
    local okCoords, x, y, z = pcall(getCharCoordinates, PLAYER_PED)
    if not okCoords then return nil end
    return findCoordinateArea(cityAreas, x, y, z)
end

local function getCurrentCrew(vehicle)
    local crew, selfText = {}, 'Сотрудник()'
    local selfOk, selfId = sampGetPlayerIdByCharHandle(PLAYER_PED)
    if selfOk then
        local okName, nick = pcall(sampGetPlayerNickname, selfId)
        if okName and nick and nick ~= '' then
            local _, surname = nick:match('([^_]+)_([^_]+)')
            selfText = (surname or nick) .. '(' .. selfId .. ')'
        end
    end
    if vehicle then
        for id = 0, 1003 do
            if id ~= selfId and sampIsPlayerConnected(id) then
                local found, ped = sampGetCharHandleBySampPlayerId(id)
                if found and getCharVehicleSafe(ped) == vehicle then
                    local okName, nick = pcall(sampGetPlayerNickname, id)
                    if okName and nick and nick ~= '' then
                        local surname = nick:match('^[^_]+_(.+)$') or nick
                        table.insert(crew, { id = id, text = surname .. '(' .. id .. ')' })
                    end
                end
            end
        end
    end
    table.sort(crew, function(a, b) return a.id < b.id end)
    local result = { selfText }
    for _, member in ipairs(crew) do table.insert(result, member.text) end
    return table.concat(result, ' и ')
end

local function refreshPatrolData()
    if not isSampAvailable() then return end
    local district = getCurrentDistrict()
    if district and district ~= '' then setBufferIfChanged(locationBuf, district) end
    local city = getCurrentCity()
    if city and city ~= '' then setBufferIfChanged(cityBuf, city) end

    local vehicle = getCharVehicleSafe(PLAYER_PED)
    if vehicle then
        setBufferIfChanged(vehicleBuf, getVehicleNameSafe(vehicle))
        setBufferIfChanged(crewBuf, getCurrentCrew(vehicle))
    else
        setBufferIfChanged(vehicleBuf, '')
        setBufferIfChanged(crewBuf, getCurrentCrew(nil))
    end
end

local function getNearestVehicle(radius)
    local okCoords, px, py, pz = pcall(getCharCoordinates, PLAYER_PED)
    if not okCoords then return nil end
    local ownVehicle = getCharVehicleSafe(PLAYER_PED)
    local okVehicles, vehicles = pcall(getAllVehicles)
    if not okVehicles or type(vehicles) ~= 'table' then return nil end

    local nearest, nearestDistance = nil, tonumber(radius) or 20.0
    for _, vehicle in ipairs(vehicles) do
        if vehicle ~= ownVehicle and doesVehicleExist(vehicle)
            and getVehicleDriverIdSafe(vehicle) ~= nil
        then
            local okVehicleCoords, x, y, z = pcall(getCarCoordinates, vehicle)
            if okVehicleCoords then
                local distance = getDistanceBetweenCoords3d(px, py, pz, x, y, z)
                if distance < nearestDistance then
                    nearest, nearestDistance = vehicle, distance
                end
            end
        end
    end
    return nearest, nearestDistance
end

local function replaceTokens(text, target, extraValues)
    local id, name
    if target then id, name = target[1], target[2] end
    local localName = getLocalName()
    local localSurname = localName:match('([^%s]+)$') or localName
    local values = {
        ['{id}'] = tostring(id or ''),
        ['{name}'] = tostring(name or ''),
        ['{myname}'] = localName,
        ['{firstname}'] = localName:match('^([^%s]+)') or localName,
        ['{surname_self}'] = localSurname,
        ['{rank}'] = trim(fromBuffer(rankBuf)),
        ['{department}'] = trim(fromBuffer(departmentBuf)),
        ['{unit}'] = trim(fromBuffer(radioTagBuf)),
        ['{vehicle}'] = trim(fromBuffer(vehicleBuf)),
        ['{city}'] = trim(fromBuffer(cityBuf)),
        ['{location}'] = trim(fromBuffer(locationBuf)),
        ['{crew}'] = trim(fromBuffer(crewBuf)),
        ['{reason}'] = trim(fromBuffer(reasonBuf)),
        ['{note}'] = trim(fromBuffer(noteBuf)),
        ['{amount}'] = tostring(ticketAmount[0]),
        ['{stars}'] = tostring(wantedLevel[0])
    }
    local city = values['{city}']
    local location = values['{location}']
    local shortCity = city == 'Los Santos' and 'LS'
        or city == 'San Fierro' and 'SF'
        or city == 'Las Venturas' and 'LV'
        or city
    values['{place}'] = city ~= '' and location ~= '' and city ~= location
        and (city .. ', район ' .. location) or (location ~= '' and location or city)
    values['{place_short}'] = shortCity ~= '' and location ~= '' and city ~= location
        and (shortCity .. ', ' .. location) or (location ~= '' and location or shortCity)
    for token, value in pairs(values) do
        local pattern = token:gsub('([%%%-%^%$%(%)%.%[%]%*%+%?])', '%%%1')
        text = text:gsub(pattern, function() return value end)
    end
    for token, value in pairs(extraValues or {}) do
        local pattern = token:gsub('([%%%-%^%$%(%)%.%[%]%*%+%?])', '%%%1')
        text = text:gsub(pattern, function() return tostring(value) end)
    end
    return text
end

local function capitalizeCp1251(text)
    text = tostring(text or '')
    if text == '' then return text end
    local first = text:sub(1, 1)
    return (cpUpperMap[first] or first:upper()) .. text:sub(2)
end

local function normalizeRpMessage(message)
    local command, body = tostring(message or ''):match('^/(%a+)%s+(.+)$')
    if not command then return tostring(message or '') end
    command = command:lower()
    body = trim(body)
    if command == 'me' then
        body = body:gsub('%.+$', '')
        return '/me ' .. body
    elseif command == 'do' then
        body = capitalizeCp1251(body)
        if not body:match('[%.%!%?]$') then body = body .. '.' end
        return '/do ' .. body
    end
    return '/' .. command .. ' ' .. body
end

local function splitLongText(text, limit)
    local chunks = {}
    local remaining = trim(text)
    while #remaining > limit do
        local head = remaining:sub(1, limit)
        local spaceAt = head:match('^.*()%s+')
        -- Не оставляем короткий тег отдельной строкой перед длинным словом.
        local splitAt = spaceAt and spaceAt > limit / 2 and spaceAt - 1 or limit
        if splitAt < 1 then splitAt = limit end
        local chunk = remaining:sub(1, splitAt)
        table.insert(chunks, chunk)
        remaining = trim(remaining:sub(splitAt + 1))
    end
    if remaining ~= '' then table.insert(chunks, remaining) end
    return chunks
end

local splitCommands = {
    n = true, s = true, f = true, fn = true,
    j = true, jn = true, r = true, rn = true, m = true
}

local function prepareMessageParts(message)
    message = normalizeRpMessage(message)
    local command, body = message:match('^/(%a+)%s+(.+)$')
    local limit
    if command == 'me' or command == 'do' then
        limit = 72
    elseif command == 'r' or command == 'rn' or command == 'f' or command == 'fn' then
        limit = 74
    elseif command == 'm' then
        limit = 72
    elseif command and splitCommands[command] then
        limit = 100
    else
        return { message }
    end
    if #body <= limit then return { message } end

    -- Многоточия тоже занимают место в серверной строке.
    local chunks = splitLongText(body, limit - 6)
    local result = {}
    for index, chunk in ipairs(chunks) do
        local prefix = command and ('/' .. command .. ' ') or ''
        if command == 'me' and index > 1 then prefix = '/do ' end
        if index > 1 then chunk = '...' .. chunk end
        if index < #chunks then
            chunk = chunk:gsub('%.+$', '') .. '...'
        elseif command == 'do' or (command == 'me' and index > 1) then
            if not chunk:match('[%.%!%?]$') then chunk = chunk .. '.' end
        end
        table.insert(result, prefix .. chunk)
    end
    return result
end

function prepareSequenceMessageParts(message)
    if tostring(message):sub(1, 1) == '/' then return prepareMessageParts(message) end
    -- Ограничиваем только речь из биндов. Ручной обычный чат не перехватываем.
    -- Не ждём серверного подтверждения, поэтому задержка остаётся заданной в настройках.
    local body = trim(tostring(message))
    if #body <= 90 then return { body } end
    local chunks = splitLongText(body, 84)
    local result = {}
    for index, chunk in ipairs(chunks) do
        local lead = index > 1 and '...' or ''
        local ending = index < #chunks and '...' or ''
        result[#result + 1] = lead .. chunk .. ending
    end
    return result
end

local outgoingSplitGuard = false

function consumeOutgoingSplitGuard(message)
    local expected = outgoingSplitGuard
    outgoingSplitGuard = false
    -- Пропускаем только конкретную строку, отправленную самим хелпером.
    -- Зависшая защита другой команды не должна отключать тег ручной /r или /f.
    return type(expected) == 'string' and type(message) == 'string'
        and expected:gsub('^/', '') == message:gsub('^/', '')
end

-- Подтверждение хранится только для собственной строки, отправляемой сейчас.
policeHelperTextAck = nil
policeHelperTextSendBusy = false

function policeHelperTextSpec(message)
    local command, body = tostring(message or ''):match('^/(%a+)%s+(.+)$')
    if not command then return nil end
    command = command:lower()
    if not splitCommands[command] then return nil end
    local limit = 90
    if command == 'r' or command == 'f' then limit = 74 end
    -- OOC-обрамление и заголовок канала оставляют меньше места для текста.
    if command == 'rn' or command == 'fn' or command == 'jn' then limit = 60 end
    if command == 'm' then limit = 72 end
    local opening, closing = '', ''
    if body:match('^%(%(%s') and body:match('%s%)%)$') then
        opening, closing = '(( ', ' ))'
        body = body:sub(4, -4)
    end
    -- Цветовые вставки нельзя считать по очищенному серверному тексту.
    if body:find('{%x%x%x%x%x%x}') then return nil end
    -- Проверяем пограничные строки, но не дробим их заранее, если они помещаются целиком.
    local confirmationLimit = (command == 'r' or command == 'f') and 60 or limit
    return { command = command, body = trim(body), limit = limit, confirmationLimit = confirmationLimit,
        opening = opening, closing = closing }
end

function policeHelperReadTextBuffer()
    local rows, counts = {}, {}
    if type(sampGetChatString) ~= 'function' then return rows, counts end
    -- Читаем только последние строки через штатную функцию, без доступа к памяти.
    for index = 75, 99 do
        local ok, text, prefix = pcall(sampGetChatString, index)
        if ok and type(text) == 'string' and text ~= '' then
            prefix = type(prefix) == 'string' and prefix or ''
            local key = prefix .. '\n' .. text
            counts[key] = (counts[key] or 0) + 1
            rows[#rows + 1] = { text = text, prefix = prefix, key = key }
        end
    end
    return rows, counts
end

function policeHelperConfirmTextBuffer(state)
    local rows, counts = policeHelperReadTextBuffer()
    for _, row in ipairs(rows) do
        -- Старые сообщения с таким же текстом не подтверждают новую отправку.
        if (counts[row.key] or 0) > ((state.bufferBefore or {})[row.key] or 0) then
            local clean = trim(stripColorCodes(row.text))
            policeHelperConfirmText(clean, nil, true)
            if not state.received and row.prefix ~= '' then
                local prefix = trim(stripColorCodes(row.prefix))
                policeHelperConfirmText(prefix .. ' ' .. clean, nil, true)
                if not state.received then policeHelperConfirmText(prefix .. ': ' .. clean, nil, true) end
            end
            if state.received or state.failed then return end
        end
    end
end

function policeHelperConfirmText(clean, playerId, fromBuffer)
    local state = policeHelperTextAck
    if not state or state.received or state.failed then return end
    if clean == 'Не флудите' or clean == 'Слишком длинное сообщение' then
        state.failed = true
        return
    end
    local posted
    if playerId ~= nil and playerId == state.id and state.wire:sub(1, #clean) == clean then
        posted = clean
    else
        -- Форматированная строка может прийти как через CLIENTMESSAGE, так и через CHAT.
        -- Для неё определяем автора по серверному заголовку, а не по типу RPC.
        local escaped = state.nickname:gsub('([^%w])', '%%%1')
        local start, finish
        if state.command == 's' then
            start, finish = clean:find(escaped .. '%[' .. state.id .. '%]%s+крикнул:%s*')
        else
            start, finish = clean:find(escaped .. '%[' .. state.id .. '%]:%s*')
            if not start then start, finish = clean:find(escaped .. ':%s*') end
        end
        if start then
            local header = clean:sub(1, start - 1)
            if header:find(':', 1, true) then return end
            local channels = { r = 'R', rn = 'RN', f = 'F', fn = 'FN', j = 'J', jn = 'JN' }
            local channel = channels[state.command]
            if channel and not header:find('[' .. channel .. ']', 1, true) then return end
            if state.command == 'm' and not header:find('<<', 1, true) then return end
            if state.command == 'n' and not header:find('((', 1, true) then return end
            if state.command == 'n' and header:find('[', 1, true) then return end
            posted = clean:sub(finish + 1)
            -- При обрезании серверное обрамление мегафона может закончиться одним >.
            if state.command == 'm' then posted = posted:gsub('%s+>>?%s*$', '') end
            if state.command == 'n' or state.command == 'rn' or state.command == 'fn' or state.command == 'jn' then
                posted = posted:gsub('%s*%)%)$', '')
            end
        end
    end
    if not posted then return end
    posted = trim(posted)
    if state.closing ~= '' then posted = posted:gsub('%s*%)%)$', '') end
    if state.opening ~= '' then posted = posted:gsub('^%(%(%s*', '') end
    -- Сверяем именно начало отправленного фрагмента, а не похожую чужую строку.
    if #posted < math.min(12, #state.wire) or state.wire:sub(1, #posted) ~= posted then return end
    local accepted = #posted - #state.lead
    if accepted < 1 or accepted > #state.piece then return end
    if (state.command == 'r' or state.command == 'f'
        or state.command == 'rn' or state.command == 'fn' or state.command == 'jn'
        or state.command == 'n' or state.command == 'm')
        and not fromBuffer and type(sampGetChatString) == 'function' then
        -- Сверяем отображённую строку: RPC может содержать больше, чем вошло в чат.
        state.eventReceived = accepted
    else
        state.received = accepted
    end
end

function sampev.onChatMessage(playerId, text)
    return safeEventCall('подтверждения обычного чата', policeHelperConfirmText, trim(stripColorCodes(text)), playerId)
end

function policeHelperTextMilliseconds()
    if type(localClock) == 'function' then
        local ok, seconds = pcall(localClock)
        if ok and type(seconds) == 'number' then return seconds * 1000 end
    end
    -- Резервный таймер нужен только если штатный таймер MoonLoader недоступен.
    return os.time() * 1000
end

function policeHelperTextElapsed(started)
    return math.max(0, policeHelperTextMilliseconds() - started)
end

function policeHelperSendConfirmedText(message, token)
    local spec = policeHelperTextSpec(message)
    if not spec then return false end
    -- Обычная короткая строка не должна ждать ответа сервера перед следующей.
    if #spec.body + #(spec.opening or '') + #(spec.closing or '') <= (spec.confirmationLimit or spec.limit) then return false end
    -- Одна очередь: подтверждения параллельных сообщений не смешиваются.
    local queuedAt = policeHelperTextMilliseconds()
    while policeHelperTextSendBusy and policeHelperTextElapsed(queuedAt) < 15000 do
        if token and token ~= sequenceToken then return true end
        wait(25)
    end
    if policeHelperTextSendBusy then
        notify('Продолжение текста отменено: очередь сообщений занята.')
        return true
    end
    local ok, id = sampGetPlayerIdByCharHandle(PLAYER_PED)
    if not ok then return false end
    local nameOk, nickname = pcall(sampGetPlayerNickname, id)
    if not nameOk or type(nickname) ~= 'string' or nickname == '' then return false end
    policeHelperTextSendBusy = true
    local remaining, index = spec.body, 1
    local lastSentAt
    while remaining ~= '' and index <= 128 do
        if token and token ~= sequenceToken then break end
        local lead = index > 1 and '...' or ''
        local budget = spec.limit - #lead - #(spec.opening or '') - #(spec.closing or '')
        local piece = splitLongText(remaining, budget)[1]
        if piece and piece:match('^%b[]:?$') and #remaining > #piece then
            piece = remaining:sub(1, budget)
        end
        if not piece or piece == '' then break end
        local state = { command = spec.command, id = id, nickname = nickname, piece = piece,
            lead = lead, wire = lead .. piece, opening = spec.opening or '', closing = spec.closing or '' }
        local _, bufferBefore = policeHelperReadTextBuffer()
        state.bufferBefore = bufferBefore
        policeHelperTextAck = state
        local prefix = spec.command ~= '' and '/' .. spec.command .. ' ' or ''
        local outgoingMessage = prefix .. state.opening .. state.wire .. state.closing
        outgoingSplitGuard = outgoingMessage
        lastSentAt = policeHelperTextMilliseconds()
        local sent = pcall(sampSendChat, outgoingMessage)
        if not sent then
            outgoingSplitGuard = false
            state.failed = true
        end
        local nextBufferPoll = 100
        while not state.received and not state.failed and policeHelperTextElapsed(lastSentAt) < 5000 do
            if token and token ~= sequenceToken then break end
            wait(25)
            local elapsed = policeHelperTextElapsed(lastSentAt)
            if elapsed >= nextBufferPoll then
                policeHelperConfirmTextBuffer(state)
                nextBufferPoll = elapsed + 100
            end
        end
        policeHelperTextAck = nil
        if not state.received then
            if #remaining > #piece and not state.failed and (not token or token == sequenceToken) then
                notify('Сервер не подтвердил текст. Продолжение остановлено, чтобы избежать повторов.')
            end
            break
        end
        remaining = trim(remaining:sub(state.received + 1))
        index = index + 1
        if remaining ~= '' then
            local interval = math.max(500, tonumber(delayMs[0]) or 1000)
            local pause = math.max(0, interval - policeHelperTextElapsed(lastSentAt))
            if pause > 0 then wait(pause) end
        end
    end
    policeHelperTextAck = nil
    policeHelperTextSendBusy = false
    return true, lastSentAt
end

function policeHelperQueueConfirmedText(message)
    lua_thread.create(function()
        if not policeHelperSendConfirmedText(message) then
            outgoingSplitGuard = message
            sampSendChat(message)
        end
    end)
end

function sendRawRpCommand(message)
    outgoingSplitGuard = message
    sampSendChat(message)
end

local function addManualRadioTag(message)
    local slash, command, body = tostring(message):match('^(/?)([rRfF])%s+(.+)$')
    if not command then return message end
    command = command:lower()
    local tag = command == 'r' and trim(fromBuffer(radioTagBuf)) or trim(fromBuffer(factionTagBuf))
    if tag == '' or body:sub(1, #tag) == tag then return message end
    return slash .. command .. ' ' .. tag .. ' ' .. body
end

local function sendPreparedParts(parts)
    lua_thread.create(function()
        for index, part in ipairs(parts) do
            outgoingSplitGuard = part
            sampSendChat(part)
            if index < #parts then wait(math.max(0, delayMs[0])) end
        end
    end)
end

function handleSendCommandEvent(message)
    if consumeOutgoingSplitGuard(message) then return end
    if type(message) ~= 'string' or message == '' then return end
    local original = message
    message = addManualRadioTag(message)
    local normalized = normalizeRpMessage(message)
    if policeHelperTextSpec(normalized) then
        policeHelperQueueConfirmedText(normalized)
        return false
    end
    local parts = prepareMessageParts(normalized)
    if #parts > 1 then
        sendPreparedParts(parts)
        return false
    elseif normalized ~= original then
        return { normalized }
    end
end


function sampev.onSendCommand(message)
    return safeEventCall('исходящей команды', handleSendCommandEvent, message)
end

function handleSendChatEvent(message)
    if consumeOutgoingSplitGuard(message) then return end
    if type(message) ~= 'string' or message == '' then return end
    message = addManualRadioTag(message)
    if policeHelperTextSpec(message) then
        policeHelperQueueConfirmedText(message)
        return false
    end
    local parts = prepareMessageParts(message)
    if #parts > 1 then
        sendPreparedParts(parts)
        return false
    end
end


function sampev.onSendChat(message)
    return safeEventCall('исходящего сообщения', handleSendChatEvent, message)
end

local function cancelSequence(silent)
    sequenceToken = sequenceToken + 1
    if sequenceBusy and not silent then notify('Текущая последовательность остановлена.') end
    sequenceBusy = false
    sequenceName = ''
    sequenceStep = 0
    sequenceTotal = 0
end

function getRoleplayCatalogEntry(name)
    for _, entry in ipairs(roleplayCatalog or {}) do
        if entry.name == name then return entry end
    end
end

function getRoleplayOverrideBody(name)
    for _, entry in ipairs(roleplayOverrides or {}) do
        if entry.name == name then return entry.body end
    end
end

function splitRoleplayBody(body)
    local result = {}
    for line in (tostring(body or '') .. '\n'):gmatch('(.-)\n') do
        line = trim(line:gsub('\r', ''))
        if line ~= '' then result[#result + 1] = line end
    end
    return result
end

function configuredRoleplayLine(name, index, fallback)
    local body = getRoleplayOverrideBody(name)
    if not body then return fallback end
    return splitRoleplayBody(body)[index] or fallback
end

function isEditableRoleplayLine(value)
    if type(value) ~= 'string' then return false end
    local command = trim(value):match('^/(%S+)')
    if not command then return true end
    command = command:lower()
    return command == 'me' or command == 'do' or command == 'todo'
end

function applyRoleplayOverrides(sequenceName, lines)
    local key = roleplaySequenceKeys[sequenceName]
    local body = key and getRoleplayOverrideBody(key)
    if not body then return lines end
    local replacements = splitRoleplayBody(body)
    local catalogEntry = getRoleplayCatalogEntry(key)
    local expectedCount = catalogEntry and #splitRoleplayBody(catalogEntry.body) or #replacements
    local editableCount = 0
    for _, line in ipairs(lines or {}) do
        if isEditableRoleplayLine(line) then editableCount = editableCount + 1 end
    end
    if editableCount ~= expectedCount then return lines end
    local result, replacementIndex = {}, 0
    for _, line in ipairs(lines or {}) do
        if isEditableRoleplayLine(line) then
            replacementIndex = replacementIndex + 1
            result[#result + 1] = replacements[replacementIndex] or line
        else
            result[#result + 1] = line
        end
    end
    return result
end

function runSequence(name, lines, options)
    options = options or {}
    lines = applyRoleplayOverrides(name, lines)
    if sequenceBusy then
        notify('Сначала дождитесь завершения действия: ' .. sequenceName .. '.')
        return
    end

    local target
    if options.target or options.targetId ~= nil then
        local id, nick, err
        if options.targetId ~= nil then
            id, nick, err = getPlayerById(options.targetId)
        else
            id, nick, err = getTarget()
        end
        if not id then notify(err); return end
        target = { id, nick }
    end

    if options.reason and trim(fromBuffer(reasonBuf)) == '' then
        notify('Укажите причину или статью.')
        return
    end

    local prepared = {}
    for _, raw in ipairs(lines) do
        if type(raw) == 'table' and (raw.wait or raw.screenshot) then
            table.insert(prepared, raw)
        else
            local message = replaceTokens(raw, target, options.tokens)
            if trim(message) ~= '' then
                if policeHelperTextSpec(message) then
                    table.insert(prepared, message)
                else
                    for _, part in ipairs(prepareSequenceMessageParts(message)) do table.insert(prepared, part) end
                end
            end
        end
    end
    if #prepared == 0 then return end

    sequenceBusy = true
    sequenceName = name
    sequenceStep = 0
    sequenceTotal = #prepared
    sequenceToken = sequenceToken + 1
    local token = sequenceToken

    lua_thread.create(function()
        for index, item in ipairs(prepared) do
            if token ~= sequenceToken then return end
            sequenceStep = index
            if type(item) == 'table' and item.wait then
                wait(math.max(0, math.min(10000, tonumber(item.wait) or 0)))
            elseif type(item) == 'table' and item.screenshot then
                if type(sampTakeScreenshot) == 'function' then
                    pcall(sampTakeScreenshot)
                elseif type(setVirtualKeyDown) == 'function' then
                    setVirtualKeyDown(vkeys.VK_F8, true)
                    wait(20)
                    setVirtualKeyDown(vkeys.VK_F8, false)
                end
            else
                local handled, lastSentAt = policeHelperSendConfirmedText(item, token)
                if not handled then
                    outgoingSplitGuard = item
                    lastSentAt = policeHelperTextMilliseconds()
                    sampSendChat(item)
                end
                if index < #prepared and type(prepared[index + 1]) ~= 'table' then
                    local interval = math.max(0, tonumber(delayMs[0]) or 1000)
                    local pause = math.max(0, interval - (lastSentAt and policeHelperTextElapsed(lastSentAt) or 0))
                    if pause > 0 then wait(pause) end
                end
            end
        end
        if token == sequenceToken then
            sequenceBusy = false
            addLog(name)
            sequenceName = ''
            sequenceStep = 0
            sequenceTotal = 0
        end
    end)
end

local function sendOne(name, text, options)
    runSequence(name, { text }, options)
end

local function unitPrefix()
    return trim(fromBuffer(radioTagBuf))
end

local function radioPrefix()
    local prefix = unitPrefix()
    return '/r ' .. (prefix ~= '' and (prefix .. ' ') or '')
end

function appendAutomaticRadioReport(lines, message)
    if autoRadioReports[0] then lines[#lines + 1] = radioPrefix() .. message end
end

local function factionPrefix()
    local prefix = trim(fromBuffer(factionTagBuf))
    return '/f ' .. (prefix ~= '' and (prefix .. ' ') or '')
end

local function radio(text)
    refreshPatrolData()
    sendOne('Доклад в рацию', radioPrefix() .. text)
end

function commandDrive(args)
    local value = trim(args)
    local seconds = tonumber(value)
    if not value:match('^%d+$') or not seconds or seconds < 5 or seconds > 30 then
        notify('Использование: /drive [секунды]. Введите число от 5 до 30, например: /drive 30.')
        return
    end
    if driveCountdownActive then
        notify('Обратный отсчёт /drive уже запущен.')
        return
    end

    driveCountdownActive = true
    driveCountdownToken = driveCountdownToken + 1
    local token = driveCountdownToken
    local threadOk, threadErr = pcall(lua_thread.create, function()
        local function sendDriveMessage(message)
            if token ~= driveCountdownToken or not isSampAvailable() then return false end
            local ok, err = pcall(sampSendChat, message)
            if not ok then protectedError('обратном отсчёте /drive', err) end
            return ok
        end

        local function secondsText(count)
            local lastTwo = count % 100
            local lastOne = count % 10
            if lastTwo < 11 or lastTwo > 14 then
                if lastOne == 1 then return 'секунда' end
                if lastOne >= 2 and lastOne <= 4 then return 'секунды' end
            end
            return 'секунд'
        end

        if not sendDriveMessage(radioPrefix() .. 'Внимание, вызываю эвакуатор!') then
            driveCountdownActive = false
            return
        end
        wait(math.max(500, delayMs[0]))
        local remaining = seconds
        while remaining > 0 do
            if not sendDriveMessage('/rn /drive - ' .. remaining .. ' ' .. secondsText(remaining) .. '!') then
                driveCountdownActive = false
                return
            end
            wait(math.min(5, remaining) * 1000)
            remaining = remaining - 5
        end
        if not sendDriveMessage('/rn !!! /drive !!!') then
            driveCountdownActive = false
            return
        end
        wait(math.max(500, delayMs[0]))
        sendDriveMessage('/drive')
        driveCountdownActive = false
    end)
    if not threadOk then
        driveCountdownActive = false
        protectedError('запуске обратного отсчёта /drive', threadErr)
    end
end

