-- Статьи и наказания заданы явно. Текст не используется для вычисления звёзд или штрафов.
legalProfiles = {
    ['Blue'] = {
        ['fineCode'] = 'АК',
        ['maxTicket'] = 0,
        ['referenceOrder'] = {
            'УК',
            'АК',
            'ПК',
            'Устав',
