                        ['entries'] = {
                            { text = 'Статья 56. Право на защитника', article = '56' },
                            { text = 'Каждое лицо вправе пользоваться помощью защитника либо адвоката.' },
                            { text = 'Статья 57. Участие адвоката', article = '57' },
                            { text = 'Адвокат вправе:' },
                            { text = 'а) присутствовать при допросе;' },
                            { text = 'б) знакомиться с материалами, затрагивающими права его доверителя;' },
                            { text = 'в) подавать жалобы и ходатайства;' },
                            { text = 'г) участвовать в судебных заседаниях.' },
                            { text = 'Статья 58. Ограничения полномочий адвоката', article = '58' },
                            { text = 'Адвокат не вправе препятствовать проведению процессуальных действий, уничтожать доказательства либо вмешиваться в деятельность сотрудников Министерства внутренних дел.' },
                        },
