local referenceLines = {}
for key, text in pairs(referenceText) do
    referenceLines[key] = {}
    for line in text:gmatch('[^\r\n]+') do
        line = trim(line)
        if line ~= '' then table.insert(referenceLines[key], line) end
    end
end

local function isChapterHeading(line)
    return line:match('^ГЛАВА%s+[IVXLCDM%d]+[%s%.]') ~= nil
        or line:match('^Глава%s+[IVXLCDM%d]+[%s%.]') ~= nil
        or line:match('^РАЗДЕЛ%s+%d+[%s%.]') ~= nil
        or line:match('^ЛЕКЦИЯ%s+%d+[%s%.]') ~= nil
        or line:match('^ПАМЯТКА%s+') ~= nil
end

function isReferenceHeading(key, line)
    if isChapterHeading(line) then return true end
    if key == 'КТО' and line:match('^%d+%.%d+[%d%.]*[%s%.]') then return true end
    return false
end

local referenceGroups = {}
local referenceGroupIndex = { ['УК'] = 1, ['АК'] = 1, ['ПК'] = 1, ['Устав'] = 1, ['Академия'] = 1, ['КТО'] = 1 }
for _, key in ipairs({ 'УК', 'АК', 'ПК', 'Устав', 'Академия', 'КТО' }) do
    referenceGroups[key] = {}
    local current = { title = 'Общие положения', lines = {} }
    table.insert(referenceGroups[key], current)
    for _, line in ipairs(referenceLines[key]) do
        if isReferenceHeading(key, line) then
            current = { title = line, lines = {} }
            table.insert(referenceGroups[key], current)
        elseif line == 'УГОЛОВНЫЙ КОДЕКС'
            or line == 'АДМИНИСТРАТИВНЫЙ КОДЕКС'
            or line == 'ПРОЦЕССУАЛЬНЫЙ КОДЕКС'
        then
            -- Название документа уже указано вкладкой и не требует отдельного раздела.
        else
            table.insert(current.lines, line)
        end
    end
    for index = #referenceGroups[key], 1, -1 do
        if #referenceGroups[key][index].lines == 0 then table.remove(referenceGroups[key], index) end
    end
end

local wantedArticles = {}
local wantedArticleList = {}
local ticketArticles = {}
local ticketArticleList = {}

local function groupArticles(list)
    local groups, index = {}, {}
    for _, article in ipairs(list) do
        local title = article.group or 'Прочее'
        if not index[title] then
            index[title] = { title = title, items = {} }
            table.insert(groups, index[title])
        end
        table.insert(index[title].items, article)
    end
    return groups
end

local wantedArticleGroups = groupArticles(wantedArticleList)
local ticketArticleGroups = groupArticles(ticketArticleList)

-- Архив Blue не подменяется чужим законодательством при смене сервера.
legalBlueReferenceGroups = referenceGroups
legalServerName = nil
activeLegalProfile = nil
legalServerAnnounced = false
legalAwaitConnection = false
legalNextServerProbe = 0
legalProfileRevision = 0

function detectLegalServerName(name)
    local clean = stripColorCodes(name):lower()
    if not clean:find('advance roleplay', 1, true) and not clean:find('advance rp', 1, true) then return nil end
    for _, server in ipairs({ 'Red', 'Green', 'Blue', 'Lime', 'Chocolate' }) do
        if clean:find('%f[%a]' .. server:lower() .. '%f[%A]') then return server end
    end
    return nil
end

function applyLegalServer(server, announce)
    local profile = legalProfiles[server or '']
    if server ~= legalServerName or profile ~= activeLegalProfile then
        local revision = legalProfileRevision + 1
        local nextReferences, nextWanted, nextWantedList = {}, {}, {}
        local nextTickets, nextTicketList = {}, {}
        if profile then
            if server == 'Blue' then
                for key, groups in pairs(legalBlueReferenceGroups) do nextReferences[key] = groups end
            end
            for key, document in pairs(profile.documents) do
                local groups = {}
                for _, chapter in ipairs(document.groups) do
                    local group = { title = chapter.title, lines = {} }
                    local previous
                    for _, entry in ipairs(chapter.entries) do
                        group.lines[#group.lines + 1] = entry.text
                        if entry.article then
                            previous = nil
                            if entry.wanted or entry.ticket then
                                local data = { article = entry.article, text = entry.text, details = {},
                                    group = chapter.title, stars = entry.stars, amount = entry.amount,
                                    variants = entry.variants, blockedReason = entry.blockedReason, revision = revision,
                                    selectNotes = entry.selectNotes, reducedStars = entry.reducedStars }
                                if entry.wanted then
                                    nextWanted[data.article] = data
                                    nextWantedList[#nextWantedList + 1] = data
                                end
                                if entry.ticket then
                                    nextTickets[data.article] = data
                                    nextTicketList[#nextTicketList + 1] = data
                                end
                                previous = data
                            end
                        elseif entry.text:match('^Статья%s+') then
                            previous = nil
                        elseif previous then
                            previous.details[#previous.details + 1] = entry.text
                        end
                    end
                    groups[#groups + 1] = group
                end
                nextReferences[key] = groups
            end
        end
        -- Новые таблицы применяются вместе, без смешения старых штрафов и новых статей.
        referenceGroups = nextReferences
        wantedArticles, wantedArticleList = nextWanted, nextWantedList
        ticketArticles, ticketArticleList = nextTickets, nextTicketList
        wantedArticleGroups = groupArticles(wantedArticleList)
        ticketArticleGroups = groupArticles(ticketArticleList)
        referenceGroupIndex = {}
        referenceNames = profile and profile.referenceOrder or {}
        referencePage = 1
        legalProfileRevision = revision
        wantedSelector[0], ticketSelector[0] = false, false
        legalServerAnnounced = false
    end
    legalServerName, activeLegalProfile = server, profile
    if announce and server and not legalServerAnnounced then
        if profile then
            notify('Определён сервер: ' .. server .. '. Загружен справочник ' .. server .. '.')
        else
            notify('Определён сервер: ' .. server .. '. Справочник этого сервера пока не добавлен.')
        end
        legalServerAnnounced = true
    end
end

function updateLegalServer(force)
    local now = os.time()
    if legalAwaitConnection or (not force and now < legalNextServerProbe) then return end
    legalNextServerProbe = now + 1
    if type(sampGetCurrentServerName) ~= 'function' then return end
    local ok, name = pcall(sampGetCurrentServerName)
    if not ok or type(name) ~= 'string' or name == '' then return end
    local server = detectLegalServerName(name)
    -- Во время загрузки имя может временно быть заглушкой. Подтверждённый сервер
    -- сбрасывается сообщением о новом подключении, а не таким временным именем.
    if server then applyLegalServer(server, true) end
end

function handleLegalConnectionMessage(clean)
    if clean:match('^Connecting to%s+') then
        legalAwaitConnection = true
        legalServerAnnounced = false
        applyLegalServer(nil, false)
    else
        local name = clean:match('^Connected to%s+(.+)')
        if name then
            legalAwaitConnection = false
            local server = detectLegalServerName(name)
            applyLegalServer(server, server ~= nil)
        end
    end
end

function requireLegalProfile()
    updateLegalServer(true)
    if activeLegalProfile then return true end
    notify(legalServerName and ('Для сервера ' .. legalServerName .. ' статьи ещё не добавлены.')
        or 'Сервер ещё не определён. Статьи другого сервера не используются.')
    return false
end

function getQuickLegalArticle(key)
    if not requireLegalProfile() then return nil end
    local code = activeLegalProfile.quick[key]
    local data
    if key == 'vstr' then data = ticketArticles[code] else data = wantedArticles[code] end
    if not data then notify('Для этой быстрой команды не задана статья текущего сервера.'); return nil end
    return data
end

local function normalizeArticle(value)
    value = trim(value):upper()
    value = value:gsub('%s+', '')
        :gsub('УК', ''):gsub('ук', '')
        :gsub('АК', ''):gsub('ак', '')
        :gsub('КоАП', ''):gsub('коап', '')
        :gsub('%.$', '')
    return value
end

