local function getPullVehicleKind(id)
    local callOk, found, ped = pcall(sampGetCharHandleBySampPlayerId, id)
    if not callOk or not found or not ped then return 'transport' end
    local vehicle = getCharVehicleSafe(ped)
    if not vehicle then return 'transport' end
    local modelOk, model = pcall(getCarModel, vehicle)
    if not modelOk or not model then return 'transport' end
    if policeHelperIsBicycleModel(model) then return 'bicycle' end
    if motorcycleModels[model] then return 'motorcycle' end
    if busModels[model] then return 'bus' end
    return 'car'
end

