function applyLegalTicketChoice(id, data, amount)
    if not activeLegalProfile or data.revision ~= legalProfileRevision then
        notify('Сервер изменился. Откройте список штрафов заново.')
        return false
    end
    if data.blockedReason then notify(data.blockedReason); return false end
    amount = tonumber(amount)
    if not amount or amount <= 0 or amount ~= math.floor(amount) then
        notify('Сначала укажите рассчитанную сумму штрафа.')
        return false
    end
    if data.variants then
        local allowed = false
        for _, variant in ipairs(data.variants) do if variant.amount == amount then allowed = true end end
        if not allowed then notify('Выберите предусмотренный статьёй вариант штрафа.'); return false end
    end
    if activeLegalProfile.maxTicket > 0 and amount > activeLegalProfile.maxTicket then
        notify('По статье 1.5 КоАП Chocolate штрафы свыше 50.000$ рассматриваются судом штата.')
        return false
    end
    commandTicket(id .. ' ' .. amount .. ' ' .. data.article .. ' ' .. activeLegalProfile.fineCode)
    return true
end

