function clearTrackedTarget(removeMarker)
    trackedTargetId = -1
    trackedTargetNickname = ''
    trackingConfirmed = false
    trackedMapId = -1
    trackedNameTextdrawId = -1
    trackedPointTextdrawId = -1
    trackedMapNextSearch = 0
    trackedMapSearchUntil = 0
    trackedWaypointX = nil
    trackedWaypointY = nil
    trackedWaypointAnnounced = false
    trackedReportSent = false
    detentionOfferId = -1
    detentionOfferUntil = 0.0
    detentionOfferShownForTargetId = -1
    if removeMarker then pcall(removeWaypoint) end
end

function startTrackedTarget(id)
    local ok, nickname = pcall(sampGetPlayerNickname, id)
    if not ok or not nickname or nickname == '' then return false end
    clearTrackedTarget(true)
    trackedTargetId = id
    trackedTargetNickname = nickname
    return true
end

function findTrackedMapTextdraws()
    if trackedTargetId < 0 or trackedTargetNickname == '' then return false end
    local mapId, nameId = -1, -1
    local pointCandidates = {}
    local targetName = lowerCp1251(trackedTargetNickname)

    for id = 0, 2304 do
        if sampTextdrawIsExists(id) then
            local ok, value = pcall(sampTextdrawGetString, id)
            if ok and value then
                local clean = trim(stripColorCodes(value))
                local lowered = lowerCp1251(clean)
                if lowered:find('samaps:map', 1, true) then
                    mapId = id
                elseif lowered == targetName then
                    nameId = id
                elseif clean == '.' then
                    local okPos, pointX, pointY = pcall(sampTextdrawGetPos, id)
                    if okPos and type(pointX) == 'number' and type(pointY) == 'number' then
                        pointCandidates[#pointCandidates + 1] = { id = id, x = pointX, y = pointY }
                    end
                end
            end
        end
    end
    if mapId == -1 or nameId == -1 then return false end

    local okName, nameX, nameY = pcall(sampTextdrawGetPos, nameId)
    if not okName or type(nameX) ~= 'number' or type(nameY) ~= 'number' then return false end
    local bestPoint, bestDistance = -1, 30.0
    for _, point in ipairs(pointCandidates) do
        local distance = math.sqrt((point.x - (nameX - 7.0)) ^ 2 + (point.y - (nameY - 7.0)) ^ 2)
        if distance < bestDistance then
            bestPoint, bestDistance = point.id, distance
        end
    end
    if bestPoint == -1 then return false end
    trackedMapId = mapId
    trackedNameTextdrawId = nameId
    trackedPointTextdrawId = bestPoint
    return true
end

function updateTrackedWaypoint()
    if trackedTargetId < 0 or not trackingConfirmed then return end

    local hadTrackedTextdraws = trackedMapId ~= -1
        and trackedNameTextdrawId ~= -1
        and trackedPointTextdrawId ~= -1
    if trackedMapId == -1 or trackedNameTextdrawId == -1 or trackedPointTextdrawId == -1
        or not sampTextdrawIsExists(trackedMapId)
        or not sampTextdrawIsExists(trackedNameTextdrawId)
        or not sampTextdrawIsExists(trackedPointTextdrawId)
    then
        trackedMapId, trackedNameTextdrawId, trackedPointTextdrawId = -1, -1, -1
        if hadTrackedTextdraws then trackedMapSearchUntil = os.clock() + 5.0 end
        if os.clock() < trackedMapNextSearch or os.clock() > trackedMapSearchUntil then return end
        trackedMapNextSearch = os.clock() + 0.5
        if not findTrackedMapTextdraws() then return end
    end

    local okMap, mapX, mapY = pcall(sampTextdrawGetPos, trackedMapId)
    local okPoint, pointX, pointY = pcall(sampTextdrawGetPos, trackedPointTextdrawId)
    local okNameText, currentName = pcall(sampTextdrawGetString, trackedNameTextdrawId)
    local okPointText, currentPoint = pcall(sampTextdrawGetString, trackedPointTextdrawId)
    if not okMap or type(mapX) ~= 'number' or type(mapY) ~= 'number'
        or not okPoint or type(pointX) ~= 'number' or type(pointY) ~= 'number'
        or not okNameText or not okPointText
        or lowerCp1251(trim(stripColorCodes(currentName))) ~= lowerCp1251(trackedTargetNickname)
        or trim(stripColorCodes(currentPoint)) ~= '.'
    then
        trackedMapId, trackedNameTextdrawId, trackedPointTextdrawId = -1, -1, -1
        trackedMapSearchUntil = os.clock() + 5.0
        return
    end

    local scale = 26.666666666667
    -- Используем позицию самой точки, а не вычисляем её через положение ника.
    -- У символа «.» координаты текстдрава указывают начало строки, поэтому учитываем центр глифа.
    local worldX = ((pointX + 1.5) - mapX) * scale - 3000.0
    local worldY = 3000.0 - ((pointY + 14.0) - mapY) * scale
    local moved = not trackedWaypointX
        or getDistanceBetweenCoords2d(trackedWaypointX, trackedWaypointY, worldX, worldY) >= 2.0
    if moved then
        trackedWaypointX, trackedWaypointY = worldX, worldY
        pcall(removeWaypoint)
        pcall(placeWaypoint, worldX, worldY, 0.0)
        if not trackedWaypointAnnounced then
            trackedWaypointAnnounced = true
            notify('GPS-точка цели перенесена на игровую карту и будет обновляться.')
        end
    end
end

function updateTrackedTargetAutomation()
    if trackedTargetId < 0 or not trackingConfirmed then return end
    if not sampIsPlayerConnected(trackedTargetId) then return end
    local found, ped = sampGetCharHandleBySampPlayerId(trackedTargetId)
    if not found or not doesCharExist(ped) then return end
    local okSelf, x1, y1, z1 = pcall(getCharCoordinates, PLAYER_PED)
    local okTarget, x2, y2, z2 = pcall(getCharCoordinates, ped)
    if not okSelf or not okTarget then return end
    local distance = getDistanceBetweenCoords3d(x1, y1, z1, x2, y2, z2)
    if distance > 100.0 then return end

    local canOfferDetention = not sampIsChatInputActive()
        and not sampIsDialogActive()
        and not isSampfuncsConsoleActive()
        and not isPauseMenuActive()
        and not window[0]
        and not quickMenu[0]
        and not wantedSelector[0]
        and not ticketSelector[0]
        and os.clock() > incomingCallUntil
        and not sosLocation.offer
        and (sharedTrackingOfferId < 0 or os.clock() > sharedTrackingOfferUntil)
    if canOfferDetention and detentionOfferShownForTargetId ~= trackedTargetId then
        detentionOfferShownForTargetId = trackedTargetId
        detentionOfferId = trackedTargetId
        detentionOfferUntil = os.clock() + 12.0
        notify('Цель ' .. trackedTargetNickname .. '[' .. trackedTargetId .. '] в '
            .. math.floor(distance + 0.5) .. ' м. Y – /y ' .. trackedTargetId
            .. ', N – отказаться.')
    end

    if autoReportTracked[0] and not trackedReportSent and os.clock() - lastAutoReportAt >= 15.0 then
        trackedReportSent = true
        lastAutoReportAt = os.clock()
        lastDamagerReportAt = lastAutoReportAt
        sampSendChat('/re Просьба проследить! ID: ' .. trackedTargetId)
    end

end

