function handleWindowMessageEvent(message, wparam, lparam)
    -- Запасной источник состояния, если Windows API недоступен.
    if message == 0x0204 or message == 0x0206 then targetRadialMenu.rightMouseDown = true end
    if message == 0x0205 or (message == 0x0006 and wparam == 0) then
        targetRadialMenu.rightMouseDown = false
    end
    if hotkeyCaptureTarget and message == 0x0100 then
        consumeWindowMessage(true, true)
        if wparam == vkeys.VK_ESCAPE then
            hotkeyCaptureTarget = nil
            return
        end
        local targets = {
            quick1 = quickKey1, quick2 = quickKey2,
            main1 = mainKey1, main2 = mainKey2,
            strobe1 = strobeKey1, strobe2 = strobeKey2,
            cruise1 = cruiseKey1, cruise2 = cruiseKey2
        }
        local target = targets[hotkeyCaptureTarget]
        if target then
            target[0] = wparam
            saveConfig()
        else
            local actionId, slot = tostring(hotkeyCaptureTarget):match('^action:([%w_]+):([12])$')
            local binding = actionId and actionHotkeys[actionId]
            if binding then
                if slot == '1' then binding.key1 = wparam else binding.key2 = wparam end
                binding.wasDown = true
                saveConfig()
            end
        end
        hotkeyCaptureTarget = nil
        hotkeyCaptureBlockUntil = os.clock() + 0.35
        return
    end

    -- В быстром меню запоминаем сам момент нажатия. Выполнение переносится
    -- в основной цикл, чтобы удержание горячей клавиши не мешало обработке кнопки mimgui.
    if quickMenu[0] and message == 0x0201 then
        quickMenuClickPending = true
        quickMenuAttackBlockUntil = os.clock() + 0.5
    end

    if targetRadialMenu.open then
        if message == 0x0201 then
            targetRadialMenu.clickPending = true
            quickMenuAttackBlockUntil = os.clock() + 0.5
        elseif message == 0x0100 and wparam == vkeys.VK_ESCAPE then
            closeTargetRadialMenu()
            consumeWindowMessage(true, true)
        end
    end

end

function onWindowMessage(message, wparam, lparam)
    return safeEventCall('оконного ввода', handleWindowMessageEvent, message, wparam, lparam)
end

