function commandDefuseBomb(args)
    local wire = lowerCp1251(trim(args))
    if wire == '' then wire = 'blue' end
    local isBlue = wire == 'blue' or wire == 'синий' or wire == 'син'
    local isRed = wire == 'red' or wire == 'красный' or wire == 'крас'
    if not isBlue and not isRed then
        notify('Использование: /bomb [blue/red]. Без аргумента выбирается синий провод.')
        return
    end
    local wireTitle = isBlue and 'Синий' or 'Красный'
    local wireDative = isBlue and 'синему проводу с положительным зарядом' or 'красному проводу с отрицательным зарядом'
    local wireAccusative = isBlue and 'синий провод' or 'красный провод'
    runSequence('Разминирование взрывного устройства', {
        '/do На поясном ремне закреплён грузовой подсумок системы MOLLE.',
        '/me лёгким движением руки отцепил грузовой подсумок и положил его на землю',
        '/me расстегнул подсумок и подготовил инструменты к использованию',
        '/me внимательно осмотрел взрывное устройство и нашёл места крепления корпуса механизма',
        '/do Корпус механизма закреплён четырьмя болтами.',
        '/me достал из подсумка универсальную отвёртку и поднёс её к болтам',
        '/me поочерёдно выкрутил болты, снял корпус механизма и отложил его в сторону',
        '/do Внутри взрывного устройства видны два провода: красный и синий.',
        '/do Синий провод имеет положительный заряд, красный – отрицательный.',
        '/me убрал отвёртку в подсумок и достал кусачки-бокорезы',
        '/do Кусачки-бокорезы имеют изолированные рукоятки для работы с электропроводкой.',
        '/me поднёс кусачки-бокорезы к {wire_dative}',
        '/me аккуратно перекусил кусачками {wire_accusative}',
        '/do {wire_title} провод перерезан, цепь детонатора разомкнута.',
        '/do Взрывное устройство разминировано.'
    }, { tokens = {
        ['{wire_title}'] = wireTitle,
        ['{wire_dative}'] = wireDative,
        ['{wire_accusative}'] = wireAccusative
    } })
end

