function stopPoliceAnimation()
    clearCharTasksImmediately(PLAYER_PED)
    animationPlaying = false
end

function playPoliceAnimation(data)
    if data.library ~= 'PED' then
        requestAnimation(data.library)
        loadAllModelsNow()
    end
    taskPlayAnim(PLAYER_PED, data.animation, data.library, 4.0, false, false, false, true, -1)
    animationPlaying = true
end

function commandAnimations(args)
    args = trim(args)
    if args == '' then
        animationWindow[0] = not animationWindow[0]
        return
    end
    local index = tonumber(args:match('^(%d+)$'))
    if not index or not policeAnimations[index] then
        notify('Использование: /nanim [1-8]. Без номера команда открывает список.')
        return
    end
    animationWindow[0] = false
    playPoliceAnimation(policeAnimations[index])
    notify('Анимация ' .. index .. ': ' .. policeAnimations[index].name .. '.')
end

function getStrobePointerSafe(car)
    if type(car) ~= 'number' or car == 0 then return nil end
    local ok, pointer = pcall(getCarPointer, car)
    if not ok or type(pointer) ~= 'number' or pointer <= 0 then return nil end
    return pointer + 1440
end

function setStrobeLamp(pointer, enabled, side)
    if pointer and pointer > 1440 then
        pcall(callMethod, 7086336, pointer, 2, 0, enabled and 1 or 0, side)
    end
end

function stopStrobes(pointer)
    strobesActive = false
    if pointer then
        setStrobeLamp(pointer, false, 0)
        setStrobeLamp(pointer, false, 1)
    end
end

function toggleStrobes()
    if not strobesEnabled[0] then return end
    if not isCharInAnyCar(PLAYER_PED)
        or isCharOnAnyBike(PLAYER_PED)
        or isCharInAnyBoat(PLAYER_PED)
        or isCharInAnyHeli(PLAYER_PED)
        or isCharInAnyPlane(PLAYER_PED)
    then
        notify('Стробоскопы доступны только в автомобиле.')
        return
    end
    if strobesActive then
        local carOk, car = pcall(storeCarCharIsInNoSave, PLAYER_PED)
        stopStrobes(carOk and getStrobePointerSafe(car) or nil)
        notify('Стробоскопы выключены.')
        return
    end
    strobesActive = true
    notify('Стробоскопы включены. SCB – сменить режим, SB – выключить.')
    notify('Чтобы сервер не глушил двигатель, приобретите «Мастер вождения»: /mn -> 7 -> 4.')
    lua_thread.create(function()
        local carOk, car = pcall(storeCarCharIsInNoSave, PLAYER_PED)
        local pointer = carOk and getStrobePointerSafe(car) or nil
        if not pointer then
            strobesActive = false
            notify('Не удалось безопасно получить указатель автомобиля.')
            return
        end
        while strobesActive and strobesEnabled[0] and isCharInAnyCar(PLAYER_PED) do
            local currentOk, currentCar = pcall(storeCarCharIsInNoSave, PLAYER_PED)
            if not currentOk or currentCar ~= car then break end
            if strobeMode == 0 then
                setStrobeLamp(pointer, true, 0); wait(100)
                setStrobeLamp(pointer, false, 0); setStrobeLamp(pointer, true, 1); wait(100)
                setStrobeLamp(pointer, false, 1)
            else
                setStrobeLamp(pointer, true, 0); setStrobeLamp(pointer, true, 1); wait(60)
                setStrobeLamp(pointer, false, 0); setStrobeLamp(pointer, false, 1); wait(60)
            end
        end
        stopStrobes(pointer)
    end)
end

function toggleCruiseControl()
    if not cruiseEnabled[0] then return end
    if not isCharInAnyCar(PLAYER_PED) then
        notify('Круиз-контроль доступен только в автомобиле.')
        return
    end
    cruiseActive = not cruiseActive
    if cruiseActive then
        local carOk, car = pcall(storeCarCharIsInNoSave, PLAYER_PED)
        local speedOk, speed = false, 0.0
        if carOk then speedOk, speed = pcall(getCarSpeed, car) end
        if not speedOk then
            cruiseActive = false
            notify('Не удалось определить скорость автомобиля.')
            return
        end
        cruiseTargetSpeed = math.max(0.0, speed)
        notify(string.format('Круиз-контроль включён: %.1f. Клавиши + и – изменяют скорость.', cruiseTargetSpeed))
    else
        notify('Круиз-контроль выключен.')
    end
end

function quickKeyName(code)
    code = tonumber(code) or 0
    if code <= 0 then return 'Не выбрана' end
    return vkeys.id_to_name(code) or ('Клавиша ' .. code)
end

function keyPairName(first, second, useSecond)
    local name = quickKeyName(first[0])
    if useSecond[0] then name = name .. ' + ' .. quickKeyName(second[0]) end
    return name
end

function quickHotkeyName()
    return keyPairName(quickKey1, quickKey2, quickUseSecond)
end

function targetRadialHotkeyName()
    return 'ПКМ + ' .. quickHotkeyName()
end

function targetRadialMenuHint()
    return 'Меню игрока: ' .. targetRadialHotkeyName()
        .. '. Наведите ПКМ на игрока и нажмите ' .. quickHotkeyName()
        .. '. ЛКМ – выбрать, Esc – закрыть.'
end

function mainHotkeyName()
    return keyPairName(mainKey1, mainKey2, mainUseSecond)
end

function hotkeyUsesPromptChoice(first, second, useSecond)
    first = tonumber(first) or 0
    second = tonumber(second) or 0
    return first == vkeys.VK_Y or first == vkeys.VK_N
        or (useSecond and (second == vkeys.VK_Y or second == vkeys.VK_N))
end

function ensureActionHotkey(id)
    if not actionHotkeys[id] then
        actionHotkeys[id] = { key1 = 0, key2 = 0, useSecond = false, wasDown = false }
    end
    return actionHotkeys[id]
end

function actionHotkeyName(id)
    local binding = ensureActionHotkey(id)
    if binding.key1 <= 0 then return 'Не назначено' end
    local name = quickKeyName(binding.key1)
    if binding.useSecond and binding.key2 > 0 then name = name .. ' + ' .. quickKeyName(binding.key2) end
    return name
end

function findActionHotkeyConflict(id)
    local binding = ensureActionHotkey(id)
    if binding.key1 <= 0 or (binding.useSecond and binding.key2 <= 0) then return nil end
    for otherId, other in pairs(actionHotkeys) do
        if otherId ~= id and other.key1 > 0 and (not other.useSecond or other.key2 > 0) then
            if not binding.useSecond and not other.useSecond and binding.key1 == other.key1 then return otherId end
            if binding.useSecond and other.useSecond then
                local sameOrder = binding.key1 == other.key1 and binding.key2 == other.key2
                local reverseOrder = binding.key1 == other.key2 and binding.key2 == other.key1
                if sameOrder or reverseOrder then return otherId end
            elseif binding.useSecond then
                if other.key1 == binding.key1 or other.key1 == binding.key2 then return otherId end
            else
                if binding.key1 == other.key1 or binding.key1 == other.key2 then return otherId end
            end
        end
    end
end

function drawWhiteNametagIds()
    if not whiteNametagIds[0] or not whiteIdFont or not isSampAvailable() then return end
    local ownOk, ownId = sampGetPlayerIdByCharHandle(PLAYER_PED)
    local ownX, ownY, ownZ = getCharCoordinates(PLAYER_PED)
    local cameraX, cameraY, cameraZ = getActiveCameraCoordinates()
    local maxId = sampGetMaxPlayerId(false)
    if not maxId or maxId < 0 then return end

    for id = 0, maxId do
        if (not ownOk or id ~= ownId) and sampIsPlayerConnected(id) then
            local exists, ped = sampGetCharHandleBySampPlayerId(id)
            if exists and doesCharExist(ped) and isCharOnScreen(ped) then
                local x, y, z = getCharCoordinates(ped)
                local headX, headY, headZ = getOffsetFromCharInWorldCoords(ped, 0.0, 0.0, 1.15)
                local visible = isLineOfSightClear(
                    cameraX, cameraY, cameraZ, headX, headY, headZ,
                    true, false, false, true, false
                )
                if visible and getDistanceBetweenCoords3d(ownX, ownY, ownZ, x, y, z) <= 25.0 then
                    local screenX, screenY = convert3DCoordsToScreen(headX, headY, headZ)
                    local idText = tostring(id)
                    local idWidth = renderGetFontDrawTextLength(whiteIdFont, idText)
                    local drawX = screenX - idWidth * 0.5
                    renderFontDrawText(whiteIdFont, idText, drawX, screenY - 22, 0xFFFFFFFF)
                end
            end
        end
    end
end

local function profileBar()
    local department = trim(fromBuffer(departmentBuf))
    local rank = trim(fromBuffer(rankBuf))
    local rpName = getLocalName()
    local profileReady = department ~= '' and rank ~= ''
    local profile = profileReady and (rpName .. ' | ' .. department .. ' | ' .. rank)
        or (rpName .. ' | Профиль ещё не получен из /st')
    if profileReady then
        imgui.TextColored(imgui.ImVec4(0.35, 0.85, 0.55, 1.0), u8(profile))
    else
        imgui.TextDisabled(u8(profile))
    end
    if sequenceBusy then
        imgui.SameLine()
        imgui.SetCursorPosX(imgui.GetWindowWidth() - 265)
        imgui.TextColored(imgui.ImVec4(1.0, 0.72, 0.25, 1.0), u8(sequenceName .. '  ' .. sequenceStep .. '/' .. sequenceTotal))
        imgui.SameLine()
        if imgui.SmallButton(u8'Стоп') then cancelSequence(false) end
    end
    imgui.Separator()
end

