function drawCenteredTabs(labels, selected, idPrefix, width)
    width = width or 135
    local style = imgui.GetStyle()
    local spacing = style.ItemSpacing.x
    local origin = imgui.GetCursorPos()
    local available = math.max(20, imgui.GetContentRegionAvail().x)
    local padding = math.max(8, style.FramePadding.x)
    local rows = {}
    local row = { items = {}, width = 0, height = 32 }
    -- Фактическая ширина текста важнее минимальной ширины кнопки.
    -- Не поместившиеся вкладки переходят в следующий центрированный ряд.
    for index, title in ipairs(labels) do
        local label = u8(title)
        local natural = imgui.CalcTextSize(label)
        local itemWidth = math.min(available, math.max(width, natural.x + padding * 2 + 2))
        local wrapped = natural.x > itemWidth - padding * 2
        local textSize = wrapped
            and imgui.CalcTextSize(label, nil, false, math.max(1, itemWidth - padding * 2 - 2)) or natural
        local gap = #row.items > 0 and spacing or 0
        if #row.items > 0 and row.width + gap + itemWidth > available then
            rows[#rows + 1] = row
            row = { items = {}, width = 0, height = 32 }
            gap = 0
        end
        row.items[#row.items + 1] = { index = index, label = label, width = itemWidth, textSize = textSize,
            wrapped = wrapped }
        row.width = row.width + gap + itemWidth
        row.height = math.max(row.height, textSize.y + style.FramePadding.y * 2)
    end
    if #row.items > 0 then rows[#rows + 1] = row end
    local result = selected
    local y = origin.y
    imgui.PushStyleVarVec2(imgui.StyleVar.ButtonTextAlign, imgui.ImVec2(0.5, 0.5))
    for _, current in ipairs(rows) do
        local x = origin.x + (available - current.width) * 0.5
        for _, item in ipairs(current.items) do
            local active = selected == item.index
            if active then
                imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(0.18, 0.43, 0.72, 1.0))
                imgui.PushStyleColor(imgui.Col.ButtonHovered, imgui.ImVec4(0.24, 0.52, 0.84, 1.0))
            end
            imgui.SetCursorPos(imgui.ImVec2(x, y))
            local buttonLabel = item.wrapped and ('##' .. idPrefix .. item.index)
                or (item.label .. '##' .. idPrefix .. item.index)
            if imgui.Button(buttonLabel, imgui.ImVec2(item.width, current.height)) then result = item.index end
            if active then imgui.PopStyleColor(2) end
            if item.wrapped then
                imgui.SetCursorPos(imgui.ImVec2(x + padding, y + (current.height - item.textSize.y) * 0.5))
                imgui.PushTextWrapPos(x + item.width - padding)
                imgui.TextUnformatted(item.label)
                imgui.PopTextWrapPos()
            end
            x = x + item.width + spacing
        end
        y = y + current.height + style.ItemSpacing.y
    end
    imgui.PopStyleVar()
    imgui.SetCursorPos(imgui.ImVec2(origin.x, y))
    imgui.Dummy(imgui.ImVec2(0, 4))
    return result
end

local function drawCommands()
    drawPageHeader('Команды', 'Команды сервера, сокращения и дополнительные возможности PoliceHelper')
    commandListMode = drawCenteredTabs({ 'Серверные команды', 'Команды PoliceHelper' }, commandListMode, 'commandMode', 230)
    imgui.TextWrapped(u8(targetRadialMenuHint()))
    imgui.Spacing()
    imgui.Separator()
    imgui.Spacing()
    imgui.BeginChild('##stableCommandList', imgui.ImVec2(0, 0), false)
    local sections = commandListMode == 1 and serverCommandSections or helperCommandSections
    for index, block in ipairs(sections) do
        imgui.SetNextItemOpen(true, imgui.Cond.Once)
        if imgui.CollapsingHeader(u8(block.title .. '##commandBlock' .. index)) then
            drawDetailedCommandRows(block.rows, '##commandColumns' .. commandListMode .. '_' .. index,
                commandListMode == 1)
            imgui.Dummy(imgui.ImVec2(0, 7))
        end
    end
    imgui.EndChild()
end

