local function targetBar()
    imgui.AlignTextToFramePadding()
    imgui.Text(u8'Цель:')
    imgui.SameLine()
    imgui.SetNextItemWidth(95)
    imgui.InputInt('##targetId', targetId, 0, 0)
    imgui.SameLine()
    if imgui.Button(u8'Из прицела', imgui.ImVec2(105, 0)) then targetFromAim() end
    imgui.SameLine()
    local id, nick = getTarget()
    if id then
        imgui.TextColored(imgui.ImVec4(0.35, 0.85, 0.55, 1.0), u8(nick .. ' [' .. id .. ']'))
    else
        imgui.TextDisabled(u8'игрок не выбран')
    end
    if sequenceBusy then
        imgui.SameLine()
        imgui.SetCursorPosX(imgui.GetWindowWidth() - 265)
        imgui.TextColored(imgui.ImVec4(1.0, 0.72, 0.25, 1.0), u8(sequenceName .. '  ' .. sequenceStep .. '/' .. sequenceTotal))
        imgui.SameLine()
        if imgui.SmallButton(u8'Стоп') then cancelSequence(false) end
    end
    imgui.Separator()
end

section = function(title)
    imgui.Spacing()
    imgui.TextColored(imgui.ImVec4(0.35, 0.65, 1.0, 1.0), u8(title))
    imgui.Dummy(imgui.ImVec2(0, 2))
end

function wideButton(label, width)
    return imgui.Button(u8(label), imgui.ImVec2(width or 180, 32))
end

function sameButton(label, width)
    imgui.SameLine()
    return wideButton(label, width)
end

inputLine = function(label, buffer, width, flags)
    imgui.AlignTextToFramePadding()
    imgui.Text(u8(label))
    imgui.SameLine()
    imgui.SetNextItemWidth(width or -1)
    return imgui.InputText(u8('##input_' .. label), buffer, ffi.sizeof(buffer), flags or 0)
end

