referenceNames = {}
local procedureOrder = { '10-55', '10-66', 'Штраф', 'Задержание' }

function matchesSearch(text)
    local query = lowerCp1251(trim(fromBuffer(searchBuf)))
    if query == '' then return true end
    return lowerCp1251(text):find(query, 1, true) ~= nil
end

function drawPairs(list)
    for _, item in ipairs(list) do
        local combined = item[1] .. ' – ' .. item[2]
        if matchesSearch(combined) then
            imgui.TextColored(imgui.ImVec4(0.42, 0.72, 1.0, 1.0), u8(item[1]))
            imgui.SameLine()
            policeHelperSafeWrappedText(item[2])
        end
    end
end

function drawReference()
    drawPageHeader('Справочник – ' .. (legalServerName or 'сервер не определён'),
        activeLegalProfile and ('Материалы сервера ' .. legalServerName .. ': ' .. table.concat(activeLegalProfile.referenceOrder, ', '))
        or 'Ожидается определение сервера: Blue, Chocolate, Red, Green или Lime')
    if not activeLegalProfile then
        policeHelperSafeWrappedText(legalServerName and ('Справочник для сервера ' .. legalServerName .. ' пока не добавлен.')
            or 'Ожидается определение сервера Advance RolePlay.')
        return
    end
    imgui.SetNextItemWidth(-1)
    imgui.InputTextWithHint('##referenceSearch', u8'Поиск: статья, нарушение, экзамен, traffic-stop, код...', searchBuf, ffi.sizeof(searchBuf))
    imgui.Spacing()
    referencePage = drawCenteredTabs(referenceNames, referencePage, 'referencePage', 88)
    imgui.Separator()

    imgui.BeginChild('##referenceBody', imgui.ImVec2(0, -1), true)
    local name = referenceNames[referencePage]
    if name == 'Коды' then
        section('Тэн-коды')
        drawPairs(tenCodes)
        section('Ситуационные коды')
        drawPairs(situationCodes)
        section('Маркировки')
        drawPairs(markings)
    elseif name == 'Порядки' then
        for _, title in ipairs(procedureOrder) do
            local lines = procedures[title]
            section(title)
            for _, line in ipairs(lines) do
                if matchesSearch(title .. ' ' .. line) then policeHelperSafeWrappedText(line) end
            end
        end
    else
        local query = trim(fromBuffer(searchBuf))
        local groups = referenceGroups[name] or {}
        if query == '' then
            local selected = referenceGroupIndex[name] or 1
            if selected > #groups then selected = 1 end
            imgui.BeginChild('##referenceChapters', imgui.ImVec2(270, 0), true)
            for index, group in ipairs(groups) do
                -- Высота пункта зависит от переноса текста и выбранного размера шрифта.
                local start = imgui.GetCursorPos()
                local width = math.max(20, imgui.GetContentRegionAvail().x)
                local label = u8(group.title)
                local textSize = imgui.CalcTextSize(label, nil, false, math.max(1, width - 12))
                local height = math.max(30, textSize.y + 12)
                if imgui.Selectable('##referenceChapter' .. index, selected == index, 0, imgui.ImVec2(width, height)) then
                    selected = index
                    referenceGroupIndex[name] = index
                end
                local nextPosition = imgui.GetCursorPos()
                imgui.SetCursorPos(imgui.ImVec2(start.x + 6, start.y + (height - textSize.y) * 0.5))
                imgui.PushTextWrapPos(start.x + width - 6)
                imgui.TextUnformatted(label)
                imgui.PopTextWrapPos()
                imgui.SetCursorPos(nextPosition)
            end
            imgui.EndChild()
            imgui.SameLine()
            imgui.BeginChild('##referenceChapterText', imgui.ImVec2(0, 0), true)
            local group = groups[selected]
            if group then
                imgui.PushTextWrapPos(0)
                section(group.title)
                imgui.PopTextWrapPos()
                for _, line in ipairs(group.lines) do
                    policeHelperSafeWrappedText(line)
                    imgui.Spacing()
                end
            end
            imgui.EndChild()
        else
            local shown = 0
            for _, group in ipairs(groups) do
                local groupShown = false
                for _, line in ipairs(group.lines) do
                    if matchesSearch(group.title .. ' ' .. line) then
                        if not groupShown then
                            imgui.PushTextWrapPos(0)
                            section(group.title)
                            imgui.PopTextWrapPos()
                            groupShown = true
                        end
                        policeHelperSafeWrappedText(line)
                        imgui.Spacing()
                        shown = shown + 1
                    end
                end
            end
            if shown == 0 then imgui.TextDisabled(u8'По вашему запросу ничего не найдено.') end
        end
    end
    imgui.EndChild()
end

function drawArticleSelector(kind)
    local isWanted = kind == 'wanted'
    local open = isWanted and wantedSelector or ticketSelector
    if not activeLegalProfile then open[0] = false; return end
    local fineCode = activeLegalProfile.fineCode
    local queryBuf = isWanted and wantedQueryBuf or ticketQueryBuf
    local groups = isWanted and wantedArticleGroups or ticketArticleGroups
    local title = (isWanted and 'Выбор статьи УК' or ('Выбор штрафа ' .. fineCode)) .. ' – ' .. legalServerName
    local id, nickname = getPlayerById(selectorTargetId)
    if not id then
        open[0] = false
        notify('Выбранный игрок вышел с сервера.')
        return
    end

    local display = imgui.GetIO().DisplaySize
    imgui.SetNextWindowPos(imgui.ImVec2(display.x * 0.5, display.y * 0.5),
        imgui.Cond.Appearing, imgui.ImVec2(0.5, 0.5))
    imgui.SetNextWindowSize(imgui.ImVec2(math.min(820, display.x - 32), math.min(650, display.y - 32)), imgui.Cond.FirstUseEver)
    if imgui.Begin(u8(title), open, imgui.WindowFlags.NoCollapse) then
        imgui.TextWrapped(u8('Игрок: ' .. nickname .. ' [' .. id .. ']. Поиск необязателен: команда только с ID открывает полный список.'))
        imgui.SetNextItemWidth(-1)
        local filterHint = isWanted and 'неподч' or 'встреч'
        imgui.InputTextWithHint('##articleFilter', u8(filterHint), queryBuf, ffi.sizeof(queryBuf))
        imgui.Spacing()

        local query = lowerCp1251(trim(fromBuffer(queryBuf)))
        local shown = 0
        imgui.BeginChild('##articleResults', imgui.ImVec2(0, 0), true)
        for groupIndex, group in ipairs(groups) do
            local groupMatches = query == '' or lowerCp1251(group.title):find(query, 1, true) ~= nil
            local matchingItems = {}
            for _, data in ipairs(group.items) do
                local combined = data.article .. ' ' .. data.text
                if groupMatches or lowerCp1251(combined):find(query, 1, true) then
                    table.insert(matchingItems, data)
                end
            end
            if #matchingItems > 0 then
                shown = shown + #matchingItems
                if query ~= '' then imgui.SetNextItemOpen(true, imgui.Cond.Always) end
                if imgui.CollapsingHeader(u8(group.title .. '##selectorGroup' .. kind .. groupIndex)) then
                    for itemIndex, data in ipairs(matchingItems) do
                        local heading
                        if isWanted then
                            heading = data.stars
                                and (data.article .. ' УК  •  ' .. data.stars .. ' уровень розыска')
                                or (data.article .. ' УК  •  уровень по основной статье')
                        else
                            heading = data.amount
                                and (data.article .. ' ' .. fineCode .. '  •  штраф ' .. data.amount .. '$')
                                or (data.article .. ' ' .. fineCode .. (data.variants and '  •  выберите условие нарушения'
                                    or data.blockedReason and '  •  без фиксированного штрафа' or '  •  сумма рассчитывается вручную'))
                        end
                        local unique = '##article' .. kind .. groupIndex .. '_' .. itemIndex
                        imgui.TextColored(imgui.ImVec4(0.42, 0.72, 1.0, 1.0), u8(heading))
                        policeHelperSafeWrappedText(data.text)
                        for _, note in ipairs(data.selectNotes or {}) do
                            policeHelperSafeWrappedText(note)
                        end
                        for _, detail in ipairs(data.details or {}) do
                            policeHelperSafeWrappedText(detail)
                        end
                        if isWanted and not data.stars then
                            imgui.Text(u8'Уровень розыска:')
                            imgui.SameLine()
                            imgui.SetNextItemWidth(90)
                            imgui.InputInt('##variableStars' .. unique, wantedVariableStars, 1, 1)
                            if wantedVariableStars[0] < 1 then wantedVariableStars[0] = 1 end
                            if wantedVariableStars[0] > 6 then wantedVariableStars[0] = 6 end
                        elseif not isWanted and not data.amount and not data.variants and not data.blockedReason then
                            imgui.Text(u8'Рассчитанная сумма:')
                            imgui.SameLine()
                            imgui.SetNextItemWidth(150)
                            imgui.InputInt('##variableAmount' .. unique, ticketVariableAmount, 1000, 5000)
                            if ticketVariableAmount[0] < 0 then ticketVariableAmount[0] = 0 end
                        end
                        if data.blockedReason then
                            policeHelperSafeWrappedText(data.blockedReason)
                        elseif not isWanted and data.variants then
                            for variantIndex, variant in ipairs(data.variants) do
                                local label = variant.label .. ' – ' .. variant.amount .. '$'
                                if imgui.Button(u8(label .. unique .. '_variant' .. variantIndex), imgui.ImVec2(0, 27)) then
                                    if applyLegalTicketChoice(id, data, variant.amount) then open[0] = false end
                                end
                            end
                        else
                        if isWanted and data.reducedStars then
                            policeHelperSafeWrappedText('При подчинении законным требованиям уровень необходимо уменьшить на 1 (примечание к главе I).')
                            if imgui.Button(u8('При подчинении: ' .. data.reducedStars .. ' уровень' .. unique .. '_reduced'), imgui.ImVec2(0, 27)) then
                                open[0] = false
                                commandSu(id .. ' ' .. data.reducedStars .. ' ' .. data.article .. ' УК')
                            end
                        end
                        local buttonText = isWanted and ('Выбрать ' .. data.article .. ' УК') or ('Выбрать ' .. data.article .. ' ' .. fineCode)
                        if imgui.Button(u8(buttonText .. unique), imgui.ImVec2(210, 27)) then
                            if isWanted then
                                local stars = data.stars or wantedVariableStars[0]
                                if stars >= 1 and stars <= 6 then
                                    open[0] = false
                                    commandSu(id .. ' ' .. stars .. ' ' .. data.article .. ' УК')
                                else
                                    notify('Укажите уровень розыска от 1 до 6.')
                                end
                            else
                                local amount = data.amount or ticketVariableAmount[0]
                                if applyLegalTicketChoice(id, data, amount) then open[0] = false end
                            end
                        end
                        end
                        imgui.Dummy(imgui.ImVec2(0, 7))
                    end
                end
            end
        end
        if shown == 0 then imgui.TextDisabled(u8'Совпадений не найдено. Измените запрос.') end
        imgui.EndChild()
    end
    imgui.End()
end

function drawKeyCapture(label, targetName, value)
    imgui.AlignTextToFramePadding()
    imgui.Text(u8(label))
    imgui.SameLine(260)
    local caption = hotkeyCaptureTarget == targetName and 'Нажмите клавишу...'
        or quickKeyName(value[0])
    if imgui.Button(u8(caption .. '##capture' .. targetName), imgui.ImVec2(220, 30)) then
        hotkeyCaptureTarget = targetName
    end
end

function normalizeEditorCommand(value)
    return trim(value):gsub('^/+', ''):lower()
end

function findEditorEntry(name)
    name = normalizeEditorCommand(name)
    for _, entry in ipairs(commandAliases) do
        if entry.name == name then return 'alias', entry end
    end
    for _, entry in ipairs(customCommands) do
        if entry.name == name then return 'custom', entry end
    end
end

