function getWeaponDrawAction(weaponId)
    local name = customWeaponNames[weaponId]
    if not name or weaponId == 0 then return nil end
    if weaponId == 1 then return 'надел ' .. name .. ' на руку' end
    if weaponId == 3 then return 'снял ' .. name .. ' с поясного держателя' end
    if weaponId >= 2 and weaponId <= 9 then return 'достал ' .. name .. ' из крепления на экипировке' end
    if weaponId >= 10 and weaponId <= 18 then return 'достал ' .. name .. ' из служебной сумки' end
    if weaponId >= 22 and weaponId <= 24 then return 'достал ' .. name .. ' из кобуры' end
    if weaponId >= 25 and weaponId <= 38 then return 'снял ' .. name .. ' с крепления за спиной' end
    if weaponId == 39 or weaponId == 40 then return 'достал ' .. name .. ' из подсумка' end
    if weaponId == 41 or weaponId == 42 then return 'достал ' .. name .. ' из служебной сумки' end
    if weaponId == 43 then return 'достал ' .. name .. ' из защитного чехла' end
    if weaponId == 44 or weaponId == 45 then return 'достал ' .. name .. ' из футляра' end
    if weaponId == 46 then return 'снял ' .. name .. ' с крепления за спиной' end
    return 'достал ' .. name
end

function getWeaponHolsterAction(weaponId)
    local name = customWeaponNames[weaponId]
    if not name or weaponId == 0 then return nil end
    if weaponId == 1 then return 'снял ' .. name .. ' с руки и убрал в подсумок' end
    if weaponId == 3 then return 'закрепил ' .. name .. ' на поясном держателе' end
    if weaponId >= 2 and weaponId <= 9 then return 'закрепил ' .. name .. ' на экипировке' end
    if weaponId >= 10 and weaponId <= 18 then return 'убрал ' .. name .. ' в служебную сумку' end
    if weaponId >= 22 and weaponId <= 24 then return 'убрал ' .. name .. ' в кобуру' end
    if weaponId >= 25 and weaponId <= 38 then return 'закрепил ' .. name .. ' за спиной' end
    if weaponId == 39 or weaponId == 40 then return 'убрал ' .. name .. ' в подсумок' end
    if weaponId == 41 or weaponId == 42 then return 'убрал ' .. name .. ' в служебную сумку' end
    if weaponId == 43 then return 'убрал ' .. name .. ' в защитный чехол' end
    if weaponId == 44 or weaponId == 45 then return 'убрал ' .. name .. ' в футляр' end
    if weaponId == 46 then return 'закрепил ' .. name .. ' за спиной' end
    return 'убрал ' .. name
end

function sendWeaponRoleplayTransition(previousId, currentId)
    if previousId == currentId then return end
    local putAway = getWeaponHolsterAction(previousId)
    local takeOut = getWeaponDrawAction(currentId)
    local action
    if putAway and takeOut then
        action = putAway .. ', затем ' .. takeOut
    else
        action = takeOut or putAway
    end
    if action then sampSendChat('/me ' .. action) end
end

function resetWeaponRoleplayState()
    local currentId = 0
    if type(getCurrentCharWeapon) == 'function' then
        local ok, value = pcall(getCurrentCharWeapon, PLAYER_PED)
        if ok and customWeaponNames[value] then currentId = value end
    end
    weaponRpInitialized = true
    weaponRpLastId = currentId
    weaponRpObservedId = currentId
    weaponRpObservedAt = os.clock()
    weaponRpLastSentAt = -100.0
end

function updateWeaponRoleplay()
    if not weaponRoleplay[0] then
        weaponRpInitialized = false
        return
    end
    if type(getCurrentCharWeapon) ~= 'function' or not doesCharExist(PLAYER_PED) then return end
    local deadOk, dead = pcall(isCharDead, PLAYER_PED)
    if deadOk and dead then
        weaponRpInitialized = false
        return
    end

    local weaponOk, currentId = pcall(getCurrentCharWeapon, PLAYER_PED)
    if not weaponOk or not customWeaponNames[currentId] then return end
    if not weaponRpInitialized then resetWeaponRoleplayState(); return end

    local now = os.clock()
    if currentId ~= weaponRpObservedId then
        weaponRpObservedId = currentId
        weaponRpObservedAt = now
        return
    end
    if currentId == weaponRpLastId or now - weaponRpObservedAt < 0.2 then return end
    if now - weaponRpLastSentAt < 0.5 then return end
    if sampIsChatInputActive() or sampIsDialogActive() or isPauseMenuActive() then return end

    local previousId = weaponRpLastId
    weaponRpLastId = currentId
    weaponRpLastSentAt = now
    sendWeaponRoleplayTransition(previousId, currentId)
end

function buildCustomCommandContext(argumentList)
    local selfId, rawNickname = -1, ''
    local selfOk, resolvedSelfId = sampGetPlayerIdByCharHandle(PLAYER_PED)
    if selfOk then
        selfId = resolvedSelfId
        local nickOk, nickname = pcall(sampGetPlayerNickname, selfId)
        if nickOk and nickname then rawNickname = nickname end
    end
    local myFirst, mySurname = rawNickname:match('^([^_]+)_([^_]+)$')
    myFirst = myFirst or getLocalName():match('^([^%s]+)') or getLocalName()
    mySurname = mySurname or getLocalName():match('%s+(.+)$') or ''

    local target
    local firstId = tonumber(argumentList[1])
    if firstId then
        local id, name = getPlayerById(firstId)
        target = { id or firstId, name or '' }
    end

    local partnerIds, partnerNames = {}, {}
    local vehicle = getCharVehicleSafe(PLAYER_PED)
    if vehicle then
        for id = 0, 1003 do
            if id ~= selfId and sampIsPlayerConnected(id) then
                local found, ped = sampGetCharHandleBySampPlayerId(id)
                if found and getCharVehicleSafe(ped) == vehicle then
                    partnerIds[#partnerIds + 1] = tostring(id)
                    local okName, nickname = pcall(sampGetPlayerNickname, id)
                    if okName and nickname then partnerNames[#partnerNames + 1] = nickname:gsub('_', ' ') end
                end
            end
        end
    end

    local weaponName = ''
    if type(getCurrentCharWeapon) == 'function' then
        local okWeapon, weaponId = pcall(getCurrentCharWeapon, PLAYER_PED)
        if okWeapon then weaponName = customWeaponNames[weaponId] or tostring(weaponId) end
    end

    local nearestVehicle = getNearestVehicle(80.0)
    local targetVehicleName = nearestVehicle and getVehicleNameSafe(nearestVehicle) or ''
    local targetVehicleColor = ''
    if nearestVehicle and type(getCarColours) == 'function' then
        local okColors, firstColor, secondColor = pcall(getCarColours, nearestVehicle)
        if okColors then targetVehicleColor = tostring(firstColor) .. '/' .. tostring(secondColor) end
    end

    local now = os.date('*t')
    local mapSquare = ''
    local squareRows = { 'А', 'Б', 'В', 'Г', 'Д', 'Ж', 'З', 'И', 'К', 'Л', 'М', 'Н',
        'О', 'П', 'Р', 'С', 'Т', 'У', 'Ф', 'Х', 'Ц', 'Ч', 'Ш', 'Я' }
    local okCoords, playerX, playerY = pcall(getCharCoordinates, PLAYER_PED)
    if okCoords then
        local row = math.ceil((-playerY + 3000) / 250)
        local column = math.ceil((playerX + 3000) / 250)
        if squareRows[row] and column >= 1 and column <= 24 then
            mapSquare = squareRows[row] .. '-' .. column
        end
    end
    local monthNames = { 'января', 'февраля', 'марта', 'апреля', 'мая', 'июня',
        'июля', 'августа', 'сентября', 'октября', 'ноября', 'декабря' }
    local dayNames = { 'воскресенье', 'понедельник', 'вторник', 'среда', 'четверг', 'пятница', 'суббота' }
    return target, {
        ['{myid}'] = selfId >= 0 and tostring(selfId) or '',
        ['{myname}'] = rawNickname ~= '' and rawNickname:gsub('_', ' ') or getLocalName(),
        ['{myfirstname}'] = myFirst,
        ['{surname}'] = mySurname,
        ['{weapon}'] = weaponName,
        ['{zone}'] = trim(fromBuffer(locationBuf)),
        ['{kvadrat}'] = mapSquare,
        ['{partner_ids}'] = table.concat(partnerIds, ', '),
        ['{partner_nicks}'] = table.concat(partnerNames, ', '),
        ['{meg_c_model}'] = targetVehicleName,
        ['{color_car}'] = targetVehicleColor,
        ['{sms}'] = lastIncomingPhone,
        ['{date}'] = string.format('%02d.%02d.%04d', now.day, now.month, now.year),
        ['{time}'] = string.format('%02d:%02d:%02d', now.hour, now.min, now.sec),
        ['{time1}'] = string.format('%02d.%02d.%04d %02d:%02d:%02d', now.day, now.month, now.year, now.hour, now.min, now.sec),
        ['{time2}'] = string.format('%02d:%02d:%02d', now.hour, now.min, now.sec),
        ['{dd}'] = string.format('%02d', now.day),
        ['{mm}'] = string.format('%02d', now.month),
        ['{YY}'] = tostring(now.year),
        ['{yy}'] = string.format('%02d', now.year % 100),
        ['{H}'] = string.format('%02d', now.hour),
        ['{M}'] = string.format('%02d', now.min),
        ['{S}'] = string.format('%02d', now.sec),
        ['{day}'] = dayNames[now.wday] or '',
        ['{month}'] = monthNames[now.month] or ''
    }
end

function executeEditorCommand(name, args)
    local kind, entry = findEditorEntry(name)
    if kind == 'alias' then
        local handler = editorBuiltInHandlers[normalizeEditorCommand(entry.target)]
        if not handler then notify('Исходная команда /' .. tostring(entry.target) .. ' недоступна.'); return end
        local ok, err = pcall(handler, args or '')
        if not ok then
            notify('Не удалось выполнить пользовательский алиас.')
            print('[PoliceHelper] Ошибка алиаса /' .. name .. ': ' .. tostring(err))
        end
        return
    end
    if kind == 'custom' then
        local prepared, argumentList = {}, {}
        local arguments = trim(args)
        for word in arguments:gmatch('%S+') do argumentList[#argumentList + 1] = word end
        local target, contextTokens = buildCustomCommandContext(argumentList)
        for line in (tostring(entry.body) .. '\n'):gmatch('(.-)\r?\n') do
            line = trim(line)
                :gsub('{args}', function() return arguments end)
                :gsub('{arg}', function() return arguments end)
                :gsub('%{%}', ' ')
            line = line:gsub('{(%d+)}', function(index) return argumentList[tonumber(index)] or '' end)
            local waitValue = line:match('^{wait:(%d+)}$') or line:match('^{wait(%d+)}$')
            if waitValue then
                prepared[#prepared + 1] = { wait = math.min(10000, tonumber(waitValue) or 0) }
            elseif line == '{F8}' or line == '{screenshot}' then
                prepared[#prepared + 1] = { screenshot = true }
            elseif line ~= '' then
                prepared[#prepared + 1] = replaceTokens(line, target, contextTokens)
            end
        end
        if #prepared == 0 then notify('У пользовательской команды нет действий.'); return end
        runSequence('Пользовательская команда /' .. name, prepared)
        return
    end
    notify('Команда /' .. name .. ' удалена. После перезапуска её имя освободится.')
end

function registerEditorCommandName(name)
    name = normalizeEditorCommand(name)
    if name == '' or editorReservedCommands[name] or editorRegisteredCommands[name] then return end
    local ok, err = pcall(sampRegisterChatCommand, name, function(args)
        return safeCommandCall(name, function(value) return executeEditorCommand(name, value) end, args)
    end)
    if ok then editorRegisteredCommands[name] = true
    else print('[PoliceHelper] Не удалось зарегистрировать /' .. name .. ': ' .. tostring(err)) end
end

function registerAllEditorCommands()
    for _, entry in ipairs(commandAliases) do registerEditorCommandName(entry.name) end
    for _, entry in ipairs(customCommands) do registerEditorCommandName(entry.name) end
end

function beginCommandEditor(mode, index)
    commandEditorMode, commandEditorIndex = mode, index or 0
    local source = mode == 'alias' and commandAliases[commandEditorIndex]
        or mode == 'custom' and customCommands[commandEditorIndex]
    setBuffer(commandEditorNameBuf, ffi.sizeof(commandEditorNameBuf), source and source.name or '')
    setBuffer(commandEditorTargetBuf, ffi.sizeof(commandEditorTargetBuf), source and source.target or '')
    setBuffer(commandEditorBodyBuf, ffi.sizeof(commandEditorBodyBuf), source and source.body or '')
end

function editorNameIsUsed(name, mode, index)
    if editorReservedCommands[name] then return true end
    for entryIndex, entry in ipairs(commandAliases) do
        if entry.name == name and not (mode == 'alias' and entryIndex == index) then return true end
    end
    for entryIndex, entry in ipairs(customCommands) do
        if entry.name == name and not (mode == 'custom' and entryIndex == index) then return true end
    end
    return false
end

function saveCommandEditorEntry()
    local name = normalizeEditorCommand(fromBuffer(commandEditorNameBuf))
    if not name:match('^[%w_]+$') then notify('Имя команды: только латинские буквы, цифры и нижнее подчёркивание.'); return end
    if editorNameIsUsed(name, commandEditorMode, commandEditorIndex) then notify('Команда /' .. name .. ' уже существует.'); return end
    if commandEditorMode == 'alias' then
        local target = normalizeEditorCommand(fromBuffer(commandEditorTargetBuf))
        if not editorBuiltInHandlers[target] then notify('Укажите команду PoliceHelper, например /hold.'); return end
        local entry = { name = name, target = target }
        if commandEditorIndex > 0 then commandAliases[commandEditorIndex] = entry else commandAliases[#commandAliases + 1] = entry end
    elseif commandEditorMode == 'custom' then
        local body = trim(fromBuffer(commandEditorBodyBuf))
        if body == '' then notify('Добавьте хотя бы одно действие.'); return end
        local entry = { name = name, body = body }
        if commandEditorIndex > 0 then customCommands[commandEditorIndex] = entry else customCommands[#customCommands + 1] = entry end
    else return end
    registerEditorCommandName(name)
    saveConfig()
    commandEditorMode, commandEditorIndex = '', 0
    notify('Команда /' .. name .. ' сохранена.')
end

function drawActionKeyCapture(actionId, slot, binding)
    local targetName = 'action:' .. actionId .. ':' .. slot
    local value = slot == '1' and binding.key1 or binding.key2
    local caption = hotkeyCaptureTarget == targetName and 'Нажмите...'
        or quickKeyName(value)
    if imgui.Button(u8(caption .. '##actionCapture' .. actionId .. slot), imgui.ImVec2(115, 27)) then
        hotkeyCaptureTarget = targetName
    end
end

function resetRecommendedActionHotkeys()
    for _, binding in pairs(actionHotkeys) do
        binding.key1, binding.key2, binding.useSecond, binding.wasDown = 0, 0, false, false
    end
    applyRecommendedActionHotkeys()
    saveConfig()
end

function drawActionHotkeys()
    section('Горячие действия')
    imgui.TextWrapped(u8'Каждому действию можно назначить одну клавишу или сочетание двух. Горячие действия не срабатывают в чате, диалогах и открытых окнах PoliceHelper.')
    imgui.TextColored(imgui.ImVec4(0.45, 0.82, 0.55, 1.0), u8'M – мегафон, J – общение, K – рация, L – снаряжение, I – ввод команды. Цифра выбирает действие; WASD остаётся свободным.')
    if imgui.Button(u8'Вернуть рекомендуемые назначения', imgui.ImVec2(285, 28)) then resetRecommendedActionHotkeys() end
    imgui.Separator()
    local categories = {
        { id = 'megaphone', title = 'Мегафон' },
        { id = 'communication', title = 'Общение' },
        { id = 'radio', title = 'Рация' },
        { id = 'equipment', title = 'Снаряжение' },
        { id = 'command_input', title = 'Заготовки команд с ID' }
    }
    imgui.BeginChild('##actionHotkeysList', imgui.ImVec2(0, 0), false)
    for _, category in ipairs(categories) do
        section(category.title)
        for _, item in ipairs(quickActionPages[category.id] or {}) do
            local binding = ensureActionHotkey(item.id)
            imgui.AlignTextToFramePadding()
            imgui.Text(u8(item.label))
            imgui.SameLine(270)
            drawActionKeyCapture(item.id, '1', binding)
            imgui.SameLine()
            local modeText = binding.useSecond and 'Две клавиши' or 'Одна клавиша'
            if imgui.Button(u8(modeText .. '##actionMode' .. item.id), imgui.ImVec2(120, 27)) then
                binding.useSecond = not binding.useSecond
                binding.wasDown = true
                saveConfig()
            end
            if binding.useSecond then
                imgui.SameLine()
                drawActionKeyCapture(item.id, '2', binding)
            end
            imgui.SameLine()
            if imgui.SmallButton(u8('Сбросить##actionClear' .. item.id)) then
                binding.key1, binding.key2, binding.useSecond, binding.wasDown = 0, 0, false, false
                saveConfig()
            end
            local conflict = findActionHotkeyConflict(item.id)
            if conflict then
                imgui.SameLine()
                imgui.TextColored(imgui.ImVec4(1.0, 0.35, 0.25, 1.0), u8('Конфликт: ' .. actionHotkeyName(conflict)))
            end
        end
    end
    imgui.EndChild()
end

