function getAliasForTarget(target)
    for _, entry in ipairs(commandAliases) do
        if normalizeEditorCommand(entry.target) == target then return entry.name end
    end
    return ''
end


function getAliasInputBuffer(target)
    if not aliasInputBuffers[target] then aliasInputBuffers[target] = newBuffer(32, getAliasForTarget(target)) end
    return aliasInputBuffers[target]
end

function initializeAliasInputBuffers()
    for _, group in ipairs(editorCommandGroups) do
        for _, item in ipairs(group.items) do getAliasInputBuffer(item[1]) end
    end
end
initializeAliasInputBuffers()

function saveAliasForTarget(target)
    local buffer = getAliasInputBuffer(target)
    local name = normalizeEditorCommand(fromBuffer(buffer))
    if name ~= '' and not name:match('^[%w_]+$') then
        notify('Имя команды: только латинские буквы, цифры и нижнее подчёркивание.')
        return
    end
    if name ~= '' then
        if editorReservedCommands[name] then notify('Команда /' .. name .. ' уже существует.'); return end
        for _, entry in ipairs(commandAliases) do
            if entry.name == name and normalizeEditorCommand(entry.target) ~= target then
                notify('Алиас /' .. name .. ' уже используется.'); return
            end
        end
        for _, entry in ipairs(customCommands) do
            if entry.name == name then notify('Команда /' .. name .. ' уже существует.'); return end
        end
    end
    for index = #commandAliases, 1, -1 do
        if normalizeEditorCommand(commandAliases[index].target) == target then table.remove(commandAliases, index) end
    end
    if name ~= '' then
        commandAliases[#commandAliases + 1] = { name = name, target = target }
        registerEditorCommandName(name)
        notify('Алиас /' .. name .. ' вызывает /' .. target .. ' с теми же аргументами.')
    else
        notify('Дополнительное имя для /' .. target .. ' удалено.')
    end
    saveConfig()
end

function saveCustomCommandForm()
    local name = normalizeEditorCommand(fromBuffer(commandEditorNameBuf))
    local body = trim(fromBuffer(commandEditorBodyBuf))
    if not name:match('^[%w_]+$') then notify('Введите имя команды без / латинскими буквами.'); return end
    if body == '' then notify('Введите текст, который должна выполнять команда.'); return end
    if editorNameIsUsed(name, 'custom', commandEditorIndex) then notify('Команда /' .. name .. ' уже существует.'); return end
    local entry = { name = name, body = body }
    if commandEditorIndex > 0 then customCommands[commandEditorIndex] = entry else customCommands[#customCommands + 1] = entry end
    registerEditorCommandName(name)
    saveConfig()
    setBuffer(commandEditorNameBuf, ffi.sizeof(commandEditorNameBuf), '')
    setBuffer(commandEditorBodyBuf, ffi.sizeof(commandEditorBodyBuf), '')
    commandEditorIndex = 0
    notify('Пользовательская команда /' .. name .. ' сохранена.')
end

function editCustomCommand(index)
    local entry = customCommands[index]
    if not entry then return end
    commandEditorIndex = index
    setBuffer(commandEditorNameBuf, ffi.sizeof(commandEditorNameBuf), entry.name)
    setBuffer(commandEditorBodyBuf, ffi.sizeof(commandEditorBodyBuf), entry.body)
end

function loadRoleplayEditor(name)
    local entry = getRoleplayCatalogEntry(name)
    if not entry then return end
    roleplayEditorSelected = name
    setBuffer(roleplayEditorBodyBuf, ffi.sizeof(roleplayEditorBodyBuf), getRoleplayOverrideBody(name) or entry.body)
end

function saveRoleplayEditor()
    local catalogEntry = getRoleplayCatalogEntry(roleplayEditorSelected)
    if not catalogEntry then return end
    local body = trim(fromBuffer(roleplayEditorBodyBuf))
    local required = #splitRoleplayBody(catalogEntry.body)
    local actual = #splitRoleplayBody(body)
    if actual ~= required then
        notify('Для этой команды нужно сохранить строк: ' .. required .. '. Сейчас указано: ' .. actual .. '.')
        return
    end
    for index = #roleplayOverrides, 1, -1 do
        if roleplayOverrides[index].name == roleplayEditorSelected then table.remove(roleplayOverrides, index) end
    end
    roleplayOverrides[#roleplayOverrides + 1] = { name = roleplayEditorSelected, body = body }
    saveConfig()
    notify('RP-отыгровка сохранена.')
end

function resetRoleplayEditor()
    local catalogEntry = getRoleplayCatalogEntry(roleplayEditorSelected)
    if not catalogEntry then return end
    for index = #roleplayOverrides, 1, -1 do
        if roleplayOverrides[index].name == roleplayEditorSelected then table.remove(roleplayOverrides, index) end
    end
    setBuffer(roleplayEditorBodyBuf, ffi.sizeof(roleplayEditorBodyBuf), catalogEntry.body)
    saveConfig()
    notify('Возвращена стандартная RP-отыгровка.')
end

function drawRoleplayEditor()
    if roleplayEditorSelected == '' and roleplayCatalog[1] then loadRoleplayEditor(roleplayCatalog[1].name) end
    imgui.TextWrapped(u8'Меняются только RP-строки выбранного действия. Серверная команда, её аргументы и порядок выполнения защищены и остаются встроенными.')
    imgui.Spacing()
    imgui.SetNextItemWidth(285)
    imgui.InputTextWithHint(u8'##roleplaySearch', u8'Поиск команды...', roleplayEditorSearchBuf, ffi.sizeof(roleplayEditorSearchBuf))
    local query = lowerCp1251(trim(fromBuffer(roleplayEditorSearchBuf)))

    imgui.BeginChild('##roleplayCatalog', imgui.ImVec2(305, 0), true)
    for _, entry in ipairs(roleplayCatalog) do
        if query == '' or lowerCp1251(entry.title):find(query, 1, true) then
            if imgui.Selectable(u8(entry.title .. '##rp_' .. entry.name), roleplayEditorSelected == entry.name, 0, imgui.ImVec2(0, 30)) then
                loadRoleplayEditor(entry.name)
            end
        end
    end
    imgui.EndChild()
    imgui.SameLine()

    imgui.BeginChild('##roleplayEditBody', imgui.ImVec2(0, 0), true)
    local selected = getRoleplayCatalogEntry(roleplayEditorSelected)
    if selected then
        imgui.TextColored(imgui.ImVec4(0.42, 0.76, 1.0, 1.0), u8(selected.title))
        imgui.TextWrapped(u8'Одна строка – одно сообщение. Количество строк изменять нельзя. Доступны штатные подстановки вроде {id}, {name}, {cmd_reason} и {cmd_amount}.')
        imgui.Spacing()
        imgui.SetNextItemWidth(-1)
        imgui.InputTextMultiline(u8('##roleplayBody_' .. selected.name), roleplayEditorBodyBuf,
            ffi.sizeof(roleplayEditorBodyBuf), imgui.ImVec2(-1, 230))
        imgui.Spacing()
        if imgui.Button(u8'Сохранить отыгровку##saveRoleplay', imgui.ImVec2(190, 31)) then saveRoleplayEditor() end
        imgui.SameLine()
        if imgui.Button(u8'Вернуть стандарт##resetRoleplay', imgui.ImVec2(170, 31)) then resetRoleplayEditor() end
    end
    imgui.EndChild()
end

function drawCommandEditor()
    imgui.SetNextItemOpen(true, imgui.Cond.Once)
    if imgui.CollapsingHeader(u8'Как использовать команды и аргументы##commandArgumentsHelp') then
        imgui.TextWrapped(u8'Алиас встроенной команды нужен, когда Вы хотите дать готовой команде более удобное имя. Никакие подстановки писать не требуется: весь текст после алиаса автоматически передаётся исходной команде.')
        imgui.TextColored(imgui.ImVec4(0.45, 0.82, 0.55, 1.0), u8'Пример: для /cuff указан алиас n. Команда /n 15 выполнит /cuff 15 со всей штатной RP-отыгровкой.')
        imgui.BulletText(u8'ID – числовой идентификатор игрока, например 15.')
        imgui.BulletText(u8'Уровень розыска – число от 1 до 6; сумма штрафа – целое число без точек и пробелов.')
        imgui.BulletText(u8'Причина или основание – оставшийся текст после обязательных чисел, например 9.1 УК или встречная полоса.')
        imgui.BulletText(u8'Аргумент в квадратных скобках необязателен: команду можно вызвать и без него.')
        imgui.Spacing()
        imgui.TextWrapped(u8'Своя команда нужна для новой фразы или последовательности, которой нет в PoliceHelper. Одна строка редактора равна одному сообщению. Строка без / отправляется в обычный чат; /me и /do создают RP-отыгровку; /r и /f отправляют сообщение в рацию; остальные команды с / отправляются серверу.')
        imgui.BulletText(u8'{args} – весь текст после команды целиком. Используйте для готового набора аргументов или причины из нескольких слов.')
        imgui.BulletText(u8'{1} – первое слово или ID после команды.')
        imgui.BulletText(u8'{2} – второе слово, {3} – третье и так далее.')
        imgui.BulletText(u8'{id} и {name} – ID из первого аргумента и имя подключённого игрока.')
        imgui.BulletText(u8'{myid}, {myname}, {firstname}, {surname} – данные своего персонажа.')
        imgui.BulletText(u8'{department}, {rank}, {unit}, {city}, {zone}, {place}, {kvadrat}, {vehicle}, {crew} – текущие данные сотрудника и патруля.')
        imgui.BulletText(u8'{partner_ids}, {partner_nicks} – пассажиры текущего автомобиля; {weapon} – оружие в руке.')
        imgui.BulletText(u8'{meg_c_model}, {color_car} – модель и цвета ближайшего транспорта; {sms} – номер последнего SMS или входящего звонка.')
        imgui.BulletText(u8'{date}, {time}, {time1}, {time2}, {dd}, {mm}, {YY}, {yy}, {H}, {M}, {S}, {day}, {month} – дата и время компьютера.')
        imgui.BulletText(u8'{} – пробел внутри шаблона.')
        imgui.BulletText(u8'{wait:500} отдельной строкой – пауза 500 мс; {F8} отдельной строкой – снимок экрана.')
        imgui.TextColored(imgui.ImVec4(0.42, 0.72, 1.0, 1.0), u8'Пример 1: команда mycuff, строка /cuff {1}. Ввод /mycuff 15 отправит /cuff 15.')
        imgui.TextColored(imgui.ImVec4(0.42, 0.72, 1.0, 1.0), u8'Пример 2: команда fine, строка /ticket {args}. Ввод /fine 15 25000 2.5 АК передаст серверу все аргументы без изменений.')
        imgui.TextColored(imgui.ImVec4(0.42, 0.72, 1.0, 1.0), u8'Пример 3: команда warn, строка Гражданин, {args}. Ввод /warn остановитесь у обочины отправит фразу в обычный чат.')
        imgui.TextDisabled(u8'Если у действия нет изменяемых данных, подстановки не нужны. Просто впишите готовый текст. Между строками применяется задержка из основных настроек.')
    end

    section('Создать свою команду')
    imgui.TextWrapped(u8'Введите команду без символа / и текст, который будет выполняться. Каждая строка отправляется по очереди с установленной задержкой.')
    imgui.AlignTextToFramePadding()
    imgui.Text(u8'Команда без /')
    imgui.SameLine(180)
    imgui.SetNextItemWidth(300)
    imgui.InputText(u8'##customCommandNameFixed', commandEditorNameBuf, ffi.sizeof(commandEditorNameBuf))
    imgui.Text(u8'Выполняемый текст – по одному сообщению в строке')
    imgui.SetNextItemWidth(-1)
    imgui.InputTextMultiline(u8'##customCommandBodyFixed', commandEditorBodyBuf, ffi.sizeof(commandEditorBodyBuf), imgui.ImVec2(-1, 92))
    imgui.TextDisabled(u8'Подстановки перечислены в раскрывающейся справке выше. Паузы разрешены от 0 до 10000 мс.')
    local saveCaption = commandEditorIndex > 0 and 'Сохранить изменения' or '+ Добавить команду'
    if imgui.Button(u8(saveCaption .. '##saveCustomFixed'), imgui.ImVec2(205, 29)) then saveCustomCommandForm() end
    if commandEditorIndex > 0 then
        imgui.SameLine()
        if imgui.Button(u8'Отмена##cancelCustomFixed', imgui.ImVec2(110, 29)) then
            commandEditorIndex = 0
            setBuffer(commandEditorNameBuf, ffi.sizeof(commandEditorNameBuf), '')
            setBuffer(commandEditorBodyBuf, ffi.sizeof(commandEditorBodyBuf), '')
        end
    end
    for index, entry in ipairs(customCommands) do
        imgui.Text(u8('/' .. entry.name))
        imgui.SameLine(180)
        if imgui.SmallButton(u8('Изменить##customFixedEdit' .. index)) then editCustomCommand(index) end
        imgui.SameLine()
        if imgui.SmallButton(u8('Удалить##customFixedDelete' .. index)) then
            table.remove(customCommands, index); commandEditorIndex = 0; saveConfig(); break
        end
    end

    section('Дополнительные имена встроенных команд')
    imgui.TextWrapped(u8'Поле напротив каждой команды создаёт дополнительное имя. Аргументы подставляются автоматически: например, alias для /cuff ID принимает тот же ID.')
    imgui.SetNextItemWidth(330)
    imgui.InputTextWithHint(u8'##aliasCommandSearch', u8'Поиск команды или описания...', aliasSearchBuf, ffi.sizeof(aliasSearchBuf))
    local query = lowerCp1251(trim(fromBuffer(aliasSearchBuf)))
    imgui.BeginChild('##stableAliasList', imgui.ImVec2(0, 460), true)
    for groupIndex, group in ipairs(editorCommandGroups) do
        local visible = {}
        for _, item in ipairs(group.items) do
            local combined = '/' .. item[1] .. ' ' .. item[2] .. ' ' .. item[3]
            if query == '' or lowerCp1251(combined):find(query, 1, true) then visible[#visible + 1] = item end
        end
        if #visible > 0 then
            imgui.SetNextItemOpen(true, imgui.Cond.Once)
            if imgui.CollapsingHeader(u8(group.title .. '##aliasGroup' .. groupIndex)) then
                for _, item in ipairs(visible) do
                    local target, arguments, description = item[1], item[2], item[3]
                    local commandText = '/' .. target .. (arguments ~= '' and (' ' .. arguments) or '')
                    imgui.TextColored(imgui.ImVec4(0.35, 0.85, 0.55, 1.0), u8(commandText))
                    imgui.SameLine(245)
                    imgui.TextDisabled(u8(description))
                    local aliasBuffer = getAliasInputBuffer(target)
                    imgui.AlignTextToFramePadding()
                    imgui.Text(u8'Новое имя без /')
                    imgui.SameLine(170)
                    imgui.SetNextItemWidth(255)
                    imgui.InputText(u8('##aliasInput_' .. target), aliasBuffer, ffi.sizeof(aliasBuffer))
                    imgui.SameLine()
                    if imgui.Button(u8('Применить##aliasApply_' .. target), imgui.ImVec2(105, 25)) then saveAliasForTarget(target) end
                    imgui.Separator()
                end
            end
        end
    end
    imgui.EndChild()
end

function drawSettings()
    drawPageHeader('Настройки', 'Профиль, автоматизация, управление, команды и горячие клавиши')
    local tabs = { 'Профиль', 'Автоматизация', 'Снаряжение', 'Автомобиль', 'Управление', 'Команды' }
    settingsPage = drawCenteredTabs(tabs, settingsPage, 'settingsTab', 130)
    imgui.BeginChild('##settingsBody', imgui.ImVec2(0, 0), true)

    if settingsPage == 1 then
        section('Профиль сотрудника')
        if imgui.RadioButtonBool(u8'Автоматически', not profileManual[0]) then
            profileManual[0] = false
            saveConfig()
            requestStatsNow()
        end
        imgui.SameLine()
        if imgui.RadioButtonBool(u8'Вручную', profileManual[0]) then
            profileManual[0] = true
            statsRequestPending = false
            saveConfig()
        end
        if profileManual[0] then
            imgui.TextWrapped(u8'Автоматическая проверка через /st отключена. Текущие данные можно изменить вручную.')
        elseif profileLoadedAutomatically then
            imgui.TextColored(imgui.ImVec4(0.35, 0.85, 0.55, 1.0), u8'Подразделение и должность получены из статистики игрока.')
        else
            imgui.TextWrapped(u8'После сообщения о заданиях скрипт отправит /st и заполнит профиль.')
        end
        local profileFlags = profileManual[0] and 0 or imgui.InputTextFlags.ReadOnly
        if inputLine('Подразделение', departmentBuf, 360, profileFlags) then saveConfig() end
        if inputLine('Должность', rankBuf, 360, profileFlags) then saveConfig() end
        if inputLine('Тег для /r', radioTagBuf, 360) then saveConfig() end
        if inputLine('Тег для /f', factionTagBuf, 360) then saveConfig() end
        if not profileManual[0] and wideButton('Обновить профиль через /st', 240) then requestStatsNow() end

        section('Отправка сообщений')
        imgui.AlignTextToFramePadding()
        imgui.Text(u8'Задержка между строками')
        imgui.SameLine(260)
        imgui.SetNextItemWidth(145)
        local delayChanged = imgui.InputInt(u8'мс##delayInput', delayMs, 0, 0)
        if delayMs[0] < 0 then delayMs[0] = 0; delayChanged = true end
        if delayMs[0] > 2000 then delayMs[0] = 2000; delayChanged = true end
        if delayChanged then saveConfig() end
        imgui.TextDisabled(u8'Введите значение от 0 до 2000 мс. Рекомендуемая задержка – 1000 мс.')

    elseif settingsPage == 2 then
        section('Чат')
        if imgui.Checkbox(u8'Делать ID игроков белым в чате', whiteMaskedChatIds) then saveConfig() end
        if imgui.Checkbox(u8'Делать ID над персонажами белым (экспериментально)', whiteNametagIds) then saveConfig() end

        section('Скрытие сообщений')
        if imgui.Checkbox(u8'Скрывать объявления /ad и строку проверки СМИ', hideAds) then saveConfig() end
        if imgui.Checkbox(u8'Скрывать канал [V]', hideVChannel) then saveConfig() end
        if imgui.Checkbox(u8'Скрывать каналы [J] и [JN]', hideJobChannels) then saveConfig() end
        if imgui.Checkbox(u8'Скрывать канал [G]', hideGChannel) then saveConfig() end
        if imgui.Checkbox(u8'Скрывать канал [P]', hidePChannel) then saveConfig() end
        if imgui.Checkbox(u8'Скрывать государственные новости', hideGovNews) then saveConfig() end
        if imgui.Checkbox(u8'Скрывать любые сообщения семьи', hideFamilyChat) then saveConfig() end
        section('Автоматические действия')
        if imgui.Checkbox(u8'Автоматически отправлять /eat при получении подноса', autoEat) then saveConfig() end
        imgui.TextWrapped(u8'Команда отправляется через 1000 мс после серверной подсказки.')
        if imgui.Checkbox(u8'Автоматически заправлять транспорт до полного бака', autoFuel) then saveConfig() end
        imgui.TextWrapped(u8'В окне АЗС количество литров определяется по тексту. Заголовок и ID диалога значения не имеют, окно скрывается автоматически.')
        imgui.TextWrapped(u8'В окне «Точное время» чистый онлайн рассчитывается автоматически: из времени в игре вычитается AFK за сегодня.')
        if imgui.Checkbox(u8'Автоматически сообщать о дамагере', autoReportDamager) then
            damagerKillTimes = {}
            lastDamagerReportAt = -100.0
            lastAutoReportAt = -100.0
            saveConfig()
        end
        imgui.TextWrapped(u8'Два убийства одним ID за 6 секунд или три за 15 секунд сразу отправляют один репорт. Между автоматическими репортами выдерживается 15 секунд.')
        if imgui.Checkbox(u8'Автоматически просить проследить найденного игрока', autoReportTracked) then
            trackedReportSent = false
            saveConfig()
        end
        imgui.TextWrapped(u8'Когда найденная через /wanted, /setmark или /sm цель окажется не дальше 100 метров, один раз отправится: /re Просьба проследить! ID: X. Общий интервал автоматических репортов – 15 секунд.')
        section('Маска')
