        builder:AddText(u8'‚„…†‡€‰‹‘’“”•–—™›№')
        interfaceGlyphRanges = imgui.ImVector_ImWchar()
        builder:BuildRanges(interfaceGlyphRanges)
        local ranges = interfaceGlyphRanges[0].Data
        local sizes = { small = 13.0, medium = 15.0, large = 18.0 }
        for name, size in pairs(sizes) do
            local ok, font = pcall(function()
                return imgui.GetIO().Fonts:AddFontFromFileTTF(fontPath, size, nil, ranges)
