imgui.OnFrame(
    function() return window[0] end,
    function(context)
        context.HideCursor = false
        -- Главное окно не должно сбрасывать газ, тормоз или движение персонажа.
        -- Видимый курсор mimgui продолжает обрабатывать элементы интерфейса сам.
        context.LockPlayer = false
        safeInterfaceFrame('главного окна', function()
        imgui.SetNextWindowSize(imgui.ImVec2(1200, 680), imgui.Cond.FirstUseEver)
        local display = imgui.GetIO().DisplaySize
        imgui.SetNextWindowPos(imgui.ImVec2(display.x * 0.5, display.y * 0.5),
            imgui.Cond.FirstUseEver, imgui.ImVec2(0.5, 0.5))
        local flags = imgui.WindowFlags.NoCollapse
        if imgui.Begin(u8(WINDOW_TITLE), window, flags) then
            drawSidebar()
            imgui.SameLine()
            imgui.BeginGroup()
            profileBar()
            imgui.BeginChild('##content', imgui.ImVec2(0, 0), false)
            if currentPage == 1 then drawCommands()
            elseif currentPage == 2 then drawRadioGuide()
            elseif currentPage == 3 then drawReference()
            elseif currentPage == 4 then drawSettings()
            end
            imgui.EndChild()
            imgui.EndGroup()
        end
        imgui.End()
        end)
    end
)

