        imgui.TextWrapped(u8'Выберите анимацию или используйте /nanim 1-8. Пробел останавливает текущую анимацию.')
        imgui.Spacing()
        for index, data in ipairs(policeAnimations) do
            if imgui.Button(u8(index .. '. ' .. data.name .. '##policeAnimation' .. index), imgui.ImVec2(200, 30)) then
                playPoliceAnimation(data)
            end
            if index % 2 == 1 then imgui.SameLine() end
        end
        imgui.Spacing()
        if imgui.Button(u8'Остановить', imgui.ImVec2(200, 30)) then stopPoliceAnimation() end
        imgui.SameLine()
        if imgui.Button(u8'Закрыть', imgui.ImVec2(200, 30)) then animationWindow[0] = false end
    end
    imgui.End()
end

