function toggleWindow()
    window[0] = not window[0]
end

function onScriptTerminate(script, quitGame)
    if script == thisScript() then
        clearSosLocationBlip()
        cancelSequence(true)
        clearTrackedTarget(true)
        stopStrobes()
        if whiteIdFont then
            pcall(renderReleaseFont, whiteIdFont)
            whiteIdFont = nil
        end
        saveConfig()
    end
end

function main()
    if not isSampfuncsLoaded() or not isSampLoaded() then return end
    while not isSampAvailable() do wait(100) end
    updateLegalServer(true)
    cleanupUpdateBackups()
    local fontOk, createdFont = pcall(renderCreateFont, 'Arial', 11, 13)
    if fontOk then
        whiteIdFont = createdFont
    else
        whiteNametagIds[0] = false
        protectedError('создании шрифта ID', createdFont)
