    registerSafeCommand('tow', commandTow)
    registerSafeCommand('wantedcar', commandWantedCar)
    registerSafeCommand('fbi', commandFbiDoor)
    registerSafeCommand('follow', commandFollow)
    registerSafeCommand('hack', commandHack)
    registerSafeCommand('names', commandNames)
    registerSafeCommand('untie', commandUntie)
    registerSafeCommand('bc', commandBodycam)
    registerSafeCommand('mask', commandMask)
    registerSafeCommand('unmask', commandUnmask)
    registerSafeCommand('healme', commandHealme)
    registerSafeCommand('gpson', commandGpsTracker)
    registerSafeCommand('gpsoff', commandGpsTrackerClear)
    registerSafeCommand('sos', commandSos)
    registerSafeCommand('sosoff', commandSosCancel)
    registerSafeCommand('r4', function()
        radio('Состав: {crew}. C\'4, доступен.')
    end)
    registerSafeCommand('r20', function()
        radio('10-20: {place}. C\'4, доступен.')
    end)
    registerSafeCommand('r3', function()
        radio('C\'3, требуется срочная поддержка. 10-20: {place}.')
    end)
    registerSafeCommand('rstart', commandPatrolStart)
    registerSafeCommand('rpat', commandPatrolStatus)
    registerSafeCommand('rend', commandPatrolEnd)
    registerSafeCommand('drive', commandDrive)

    editorBuiltInHandlers = {
        ph = function() toggleWindow() end, phsync = function() requestStatsNow() end,
        sp = commandServerPass,
        hr = commandInterview,
        nanim = commandAnimations, udo = commandUdo, prava = commandRights,
        cuff = commandCuff, cf = commandCuff, uncuff = commandUncuff, uncf = commandUncf,
        hold = commandHold, hd = commandHold,
        search = commandSearch, se = commandSearch,
        putpl = commandPutpl, pl = commandPutpl, pull = commandPull,
        arrest = commandArrest, clear = commandClear, su = commandSu,
        pg = commandQuickDisobedience, vn = commandQuickArmedAttack,
        sus = commandSmartWanted, ticket = commandTicket, tick = commandSmartTicket,
        vstr = commandQuickOncomingTicket,
        m55 = commandM55, m66 = commandM66, pr = commandStopChase,
        dk = commandMegaphoneRoadCode, proc = commandMegaphoneProcedure,
        dor = commandMegaphoneYieldRoad, sm = commandSetmark, setmark = commandSetmark,
        eject = commandEject, wanted = commandWanted, wd = commandWanted, his = commandHistory,
        y = commandDetentionMode, krik = commandShout, takelic = commandTakeLicense,
        takefish = commandTakeFish, skip = commandPass, ['break'] = commandBarrier,
        d = commandDepartmentDoors, invite = commandInvite, uninvite = commandUninvite,
        uninviteoff = commandUninviteOffline, rang = commandRang, offrang = commandOfflineRang,
        cs = commandChangeSkin, changeskin = commandChangeSkinLeader,
        nar = commandTakeDrugs, pt = commandTakeAmmo,
        bomb = commandDefuseBomb,
        fo = commandFollowOn, foff = commandFollowOff, pp = commandPhoneAccept,
        hh = commandPhoneDecline, ln = commandLeaderOoc,
        form = commandForm, jailcam = commandJailCamera,
        jaildoor = commandJailDoor, open = commandBarrierGate, signal = commandSignal,
        tow = commandTow, wantedcar = commandWantedCar, fbi = commandFbiDoor,
        follow = commandFollow, hack = commandHack, names = commandNames,
        untie = commandUntie, bc = commandBodycam, mask = commandMask,
        unmask = commandUnmask, healme = commandHealme, gpson = commandGpsTracker,
        gpsoff = commandGpsTrackerClear, sos = commandSos, sosoff = commandSosCancel,
        r4 = function() radio('Состав: {crew}. C\'4, доступен.') end,
        r20 = function() radio('10-20: {place}. C\'4, доступен.') end,
        r3 = function() radio('C\'3, требуется срочная поддержка. 10-20: {place}.') end,
        rstart = commandPatrolStart, rpat = commandPatrolStatus, rend = commandPatrolEnd,
        drive = commandDrive
    }
    for commandName in pairs(editorBuiltInHandlers) do editorReservedCommands[commandName] = true end
    registerAllEditorCommands()
    notify('Загружен. Главное меню: /ph или ' .. mainHotkeyName() .. '. Быстрый доступ: удерживать ' .. quickHotkeyName() .. '.')
    notify('Меню игрока: ' .. targetRadialHotkeyName() .. '. Наведитесь ПКМ на игрока, затем нажмите ' .. quickHotkeyName() .. '.')
    if UPDATE_MANIFEST_URL ~= '' then
        lua_thread.create(function()
            while not isSampAvailable() or not sampIsLocalPlayerSpawned() do wait(500) end
            wait(10000)
            checkForPoliceHelperUpdate(false)
        end)
    end

    local nextPatrolRefresh = 0
    local nextTrackingUpdate = 0
    local nextWeaponCheck = 0
    while true do
        wait(0)
        if updateState.manualCheckRequested or updateState.downloadRequest
            or updateState.event or updateState.deadline > 0
        then
            safeRuntimeCall('обработки обновления', processUpdaterMainThread)
        end
        if whiteNametagIds[0] then
            local renderOk, renderError = pcall(drawWhiteNametagIds)
            if not renderOk then
                whiteNametagIds[0] = false
                saveConfig()
                notify('Белые ID над игроками отключены из-за ошибки отрисовки.')
                print('[PoliceHelper] Ошибка отрисовки ID: ' .. tostring(renderError))
            end
        end
        local runtimeNow = os.clock()
        safeRuntimeCall('определения сервера', updateLegalServer)
        if sosEscalationActive then
            if sosEscalationAwaiting and sosEscalationExpiresAt > 0
                and runtimeNow > sosEscalationExpiresAt
            then
                sosEscalationActive = false
                sosEscalationAwaiting = false
                sosEscalationId = -1
                sosEscalationConfirmed = 0
                sosEscalationNextAt = 0.0
                sosEscalationExpiresAt = 0.0
                notify('Повторение SOS остановлено: сервер не подтвердил выдачу розыска.')
            elseif not sosEscalationAwaiting and sosEscalationNextAt > 0
                and runtimeNow >= sosEscalationNextAt and not sequenceBusy
            then
                safeRuntimeCall('повторения SOS', function() sendSosEscalationStep(false) end)
            end
        end
        if putplRpClosePending and runtimeNow >= putplRpCloseAt then
            putplRpClosePending = false
            putplRpCloseAt = 0.0
            safeRuntimeCall('завершения посадки в транспорт', function()
                sampSendChat(configuredRoleplayLine('putpl', 3, '/me закрыл дверь патрульного автомобиля'))
            end)
        end
        if pendingWantedTargetId >= 0 and runtimeNow > pendingWantedExpiresAt then
            pendingWantedTargetId = -1
            pendingWantedTargetNickname = ''
            pendingWantedReason = ''
            pendingWantedRetryUsed = false
            pendingWantedRoleplayKey = 'su'
            pendingWantedRoleplayFallback = '/me внёс данные подозреваемого в базу розыска'
            pendingWantedExpiresAt = 0.0
        end
        if pullRpPendingId >= 0 and runtimeNow > pullRpPendingUntil then
            pullRpPendingId = -1
            pullRpPendingNickname = ''
            pullRpPendingActor = ''
            pullRpPendingUntil = 0.0
            pullRpPendingFirst = ''
            pullRpPendingSecond = ''
        end
        if sharedTrackingOfferId >= 0 and runtimeNow > sharedTrackingOfferUntil then
            sharedTrackingOfferId = -1
            sharedTrackingOfferName = ''
            sharedTrackingOfferUntil = 0.0
        end
        if detentionOfferId >= 0 and runtimeNow > detentionOfferUntil then
            detentionOfferId = -1
            detentionOfferUntil = 0.0
        end
        if sharedTrackingSwitchId >= 0 and runtimeNow > sharedTrackingSwitchUntil then
            sharedTrackingSwitchId = -1
            sharedTrackingSwitchName = ''
            sharedTrackingSwitchUntil = 0.0
            notify('Сервер не подтвердил отключение прежнего отслеживания.')
        end
        if quickMenuPendingAction then
            local action = quickMenuPendingAction
            quickMenuPendingAction = nil
            safeRuntimeCall('быстрого меню', action)
        end
        if os.time() >= nextPatrolRefresh then
            safeRuntimeCall('данных патруля', refreshPatrolData)
            nextPatrolRefresh = os.time() + 1
        end
        if os.clock() >= nextTrackingUpdate then
            safeRuntimeCall('GPS-метки', updateTrackedWaypoint)
            safeRuntimeCall('автоматизации отслеживания', updateTrackedTargetAutomation)
            nextTrackingUpdate = os.clock() + 0.75
        end
        if os.clock() >= nextWeaponCheck then
            safeRuntimeCall('RP-отыгровок оружия', updateWeaponRoleplay)
            nextWeaponCheck = os.clock() + 0.1
        end
        if targetRadialMenu.blockAttackUntilRelease and not isKeyDown(vkeys.VK_LBUTTON) then
            targetRadialMenu.blockAttackUntilRelease = false
            quickMenuAttackBlockUntil = os.clock() + 0.5
        end
        if quickMenu[0] or targetRadialMenu.open or targetRadialMenu.blockAttackUntilRelease
            or os.clock() < quickMenuAttackBlockUntil then
            -- После выбора атака/выстрел дополнительно блокируются ещё 500 мс.
            pcall(setGameKeyState, 17, 0)
        end
        local inputFree = not sampIsChatInputActive()
            and not sampIsDialogActive()
            and not isSampfuncsConsoleActive()
            and not isPauseMenuActive()

        if targetRadialMenu.open and (not inputFree or not doesCharExist(PLAYER_PED)
            or isCharDead(PLAYER_PED) or runtimeNow - targetRadialMenu.openedAt > 30.0) then
            closeTargetRadialMenu()
        end

        local actionHotkeysAllowed = inputFree
            and os.clock() >= hotkeyCaptureBlockUntil
            and not hotkeyCaptureTarget
            and not window[0]
            and not quickMenu[0]
            and not targetRadialMenu.open
            and not wantedSelector[0]
            and not ticketSelector[0]
            and not sosConfirm[0]
            and not updateConfirm[0]
        local incomingCallActive = runtimeNow <= incomingCallUntil
        updateSosLocation(runtimeNow)
        local sosLocationOfferActive = sosLocation.offer ~= nil
        local sharedTrackingOfferActive = sharedTrackingOfferId >= 0
            and runtimeNow <= sharedTrackingOfferUntil
        local detentionOfferActive = detentionOfferId >= 0
            and runtimeNow <= detentionOfferUntil
        local promptChoiceActive = incomingCallActive or sosLocationOfferActive or sharedTrackingOfferActive
            or detentionOfferActive
        if actionHotkeysAllowed then
            if incomingCallActive then
                if wasKeyPressed(vkeys.VK_Y) then
                    safeRuntimeCall('ответа на звонок', commandPhoneAccept)
                elseif wasKeyPressed(vkeys.VK_N) then
                    safeRuntimeCall('отклонения звонка', commandPhoneDecline)
                end
            elseif sosLocationOfferActive then
                if wasKeyPressed(vkeys.VK_Y) then
                    safeRuntimeCall('метки SOS', acceptSosLocation)
                elseif wasKeyPressed(vkeys.VK_N) then
                    sosLocation.offer = nil
                    notify('Метка SOS отклонена.')
                end
            elseif sharedTrackingOfferActive then
                if wasKeyPressed(vkeys.VK_Y) then
                    local offerId = sharedTrackingOfferId
                    local offerName = sharedTrackingOfferName
                    sharedTrackingOfferId = -1
                    sharedTrackingOfferName = ''
                    sharedTrackingOfferUntil = 0.0
                    if trackedTargetId == offerId and trackingConfirmed then
                        notify('Дело №' .. offerId .. ' уже отслеживается. Текущая метка сохранена.')
                    elseif trackedTargetId >= 0 and trackingConfirmed then
                        sharedTrackingSwitchId = offerId
                        sharedTrackingSwitchName = offerName
                        sharedTrackingSwitchUntil = os.clock() + 15.0
                        safeRuntimeCall('отключения прежнего GPS-отслеживания', function()
                            sampSendChat('/setmark ' .. offerId)
                        end)
                        notify('Отключается прежнее отслеживание. После подтверждения сервера новая цель будет предложена повторно.')
                    else
                        safeRuntimeCall('совместного GPS-отслеживания', function()
                            commandSetmark(tostring(offerId))
                        end)
                    end
                elseif wasKeyPressed(vkeys.VK_N) then
                    sharedTrackingOfferId = -1
                    sharedTrackingOfferName = ''
                    sharedTrackingOfferUntil = 0.0
                    notify('Совместное отслеживание отклонено.')
                end
            elseif detentionOfferActive then
                if wasKeyPressed(vkeys.VK_Y) then
                    local offerId = detentionOfferId
                    detentionOfferId = -1
                    detentionOfferUntil = 0.0
                    if trackedTargetId == offerId and trackingConfirmed
                        and sampIsPlayerConnected(offerId)
                    then
                        safeRuntimeCall('режима задержания', function()
                            commandDetentionMode(tostring(offerId))
                        end)
                    else
                        notify('Цель больше не отслеживается.')
                    end
                elseif wasKeyPressed(vkeys.VK_N) then
                    detentionOfferId = -1
                    detentionOfferUntil = 0.0
                    notify('Режим задержания отклонён.')
                end
            end
        end
        for pageId, items in pairs(quickActionPages) do
            if pageId ~= 'main' then
                for _, item in ipairs(items) do
                    local binding = ensureActionHotkey(item.id)
                    local firstDown = binding.key1 > 0 and isKeyDown(binding.key1)
                    local secondDown = not binding.useSecond
                        or (binding.key2 > 0 and isKeyDown(binding.key2))
                    local isDown = firstDown and secondDown
                    local choiceConflict = promptChoiceActive
                        and hotkeyUsesPromptChoice(binding.key1, binding.key2, binding.useSecond)
                    if actionHotkeysAllowed and not choiceConflict and isDown and not binding.wasDown
                        and not findActionHotkeyConflict(item.id)
                    then
                        safeRuntimeCall('горячего действия ' .. item.id, item.action)
                    end
                    binding.wasDown = isDown
                end
            end
        end
        if animationPlaying and inputFree and wasKeyPressed(vkeys.VK_SPACE) then stopPoliceAnimation() end

        local strobePrimaryDown = strobeKey1[0] > 0 and isKeyDown(strobeKey1[0])
        local strobeSecondDown = not strobeUseSecond[0]
            or (strobeKey2[0] > 0 and isKeyDown(strobeKey2[0]))
        local strobeHotkeyDown = strobePrimaryDown and strobeSecondDown
        if actionHotkeysAllowed and strobesEnabled[0]
            and not (promptChoiceActive and hotkeyUsesPromptChoice(
                strobeKey1[0], strobeKey2[0], strobeUseSecond[0]
            ))
            and strobeHotkeyDown and not strobeHotkeyWasDown
        then
            toggleStrobes()
        end
        strobeHotkeyWasDown = strobeHotkeyDown

        if actionHotkeysAllowed and strobesEnabled[0] then
            if testCheat('scb') then
                strobeMode = strobeMode == 0 and 1 or 0
                notify('Режим стробоскопов: ' .. (strobeMode + 1) .. '.')
            end
        end

        local cruisePrimaryDown = cruiseKey1[0] > 0 and isKeyDown(cruiseKey1[0])
        local cruiseSecondDown = not cruiseUseSecond[0]
            or (cruiseKey2[0] > 0 and isKeyDown(cruiseKey2[0]))
        local cruiseHotkeyDown = cruisePrimaryDown and cruiseSecondDown
        if actionHotkeysAllowed and cruiseEnabled[0]
            and not (promptChoiceActive and hotkeyUsesPromptChoice(
                cruiseKey1[0], cruiseKey2[0], cruiseUseSecond[0]
            ))
            and cruiseHotkeyDown and not cruiseHotkeyWasDown
        then
            toggleCruiseControl()
        end
        cruiseHotkeyWasDown = cruiseHotkeyDown
        if cruiseActive then
            if not cruiseEnabled[0] or not isCharInAnyCar(PLAYER_PED) or isKeyDown(vkeys.VK_S) then
                cruiseActive = false
            else
                if wasKeyPressed(187) then
                    cruiseTargetSpeed = cruiseTargetSpeed + 2.5
                    notify(string.format('Скорость круиз-контроля: %.1f.', cruiseTargetSpeed))
                elseif wasKeyPressed(189) then
                    cruiseTargetSpeed = math.max(0.0, cruiseTargetSpeed - 2.5)
                    notify(string.format('Скорость круиз-контроля: %.1f.', cruiseTargetSpeed))
                end
                local carOk, car = pcall(storeCarCharIsInNoSave, PLAYER_PED)
                local speedOk, speed = false, 0.0
                if carOk then speedOk, speed = pcall(getCarSpeed, car) end
                if not speedOk then
                    cruiseActive = false
                elseif speed < cruiseTargetSpeed then
                    local memoryOk, memoryError = pcall(writeMemory, 12006520, 1, 255, false)
                    if not memoryOk then
                        cruiseActive = false
                        notify('Круиз-контроль отключён из-за ошибки доступа к памяти.')
                        print('[PoliceHelper] Ошибка круиз-контроля: ' .. tostring(memoryError))
                    end
                end
            end
        end
        local mainPrimaryDown = mainKey1[0] > 0 and isKeyDown(mainKey1[0])
        local mainSecondDown = not mainUseSecond[0]
            or (mainKey2[0] > 0 and isKeyDown(mainKey2[0]))
        local mainHotkeyDown = mainPrimaryDown and mainSecondDown
        if mainHotkeyDown and not mainHotkeyWasDown
            and os.clock() >= hotkeyCaptureBlockUntil
            and not (promptChoiceActive and hotkeyUsesPromptChoice(
                mainKey1[0], mainKey2[0], mainUseSecond[0]
            ))
            and not quickMenu[0]
            and not targetRadialMenu.open
            and not sosConfirm[0]
            and not updateConfirm[0]
            and not sampIsChatInputActive()
            and not sampIsDialogActive()
            and not isSampfuncsConsoleActive()
            and not isPauseMenuActive()
        then
            toggleWindow()
        end
        mainHotkeyWasDown = mainHotkeyDown

        local primaryDown = quickKey1[0] > 0 and isKeyDown(quickKey1[0])
        local secondDown = not quickUseSecond[0]
            or (quickKey2[0] > 0 and isKeyDown(quickKey2[0]))
        local quickHotkeyDown = primaryDown and secondDown
        if quickHotkeyDown and not quickHotkeyWasDown
            and os.clock() >= hotkeyCaptureBlockUntil
            and not (promptChoiceActive and hotkeyUsesPromptChoice(
                quickKey1[0], quickKey2[0], quickUseSecond[0]
            ))
            and not quickMenuBlocked
            and not targetRadialMenu.open
            and not window[0]
            and not wantedSelector[0]
            and not ticketSelector[0]
            and not sosConfirm[0]
            and not updateConfirm[0]
            and not interviewWindow[0]
            and not animationWindow[0]
            and not sampIsChatInputActive()
            and not sampIsDialogActive()
            and not isSampfuncsConsoleActive()
            and not isPauseMenuActive()
        then
            if targetRadialRightMouseDown() then
                safeRuntimeCall('открытия кругового меню игрока', openTargetRadialMenu)
            else
                quickMenuPage = 'main'
                quickMenuNeedsFocus = true
                quickMenu[0] = true
            end
        end
        if quickMenu[0] and (not quickHotkeyDown
            or sampIsChatInputActive()
            or sampIsDialogActive()
            or isPauseMenuActive())
        then
            quickMenu[0] = false
        end
        if quickMenuBlocked and not quickHotkeyDown then quickMenuBlocked = false end
        quickHotkeyWasDown = quickHotkeyDown
    end
end
